//
// Misc: Miscellaneous
//

.border-transparent {
  border-color: transparent !important !important ;
}

// Description Blocks
.description-block {
  display: block !important ;
  margin: 10px 0 !important ;
  text-align: center !important ;

  &.margin-bottom {
    margin-bottom: 25px !important ;
  }

  > .description-header {
    font-size: 16px !important ;
    font-weight: 600 !important ;
    margin: 0 !important ;
    padding: 0 !important ;
  }

  > .description-text {
    text-transform: uppercase !important ;
  }

  // Description Block Extension
  .description-icon {
    font-size: 16px !important ;
  }
}

// List utility classes
.list-group-unbordered {
  > .list-group-item {
    border-left: 0 !important ;
    border-radius: 0 !important ;
    border-right: 0 !important ;
    padding-left: 0 !important ;
    padding-right: 0 !important ;
  }
}

.list-header {
  color: $gray-600 !important ;
  font-size: 15px !important ;
  font-weight: 700 !important ;
  padding: 10px 4px !important ;
}

.list-seperator {
  background-color: $card-border-color !important ;
  height: 1px !important ;
  margin: 15px 0 9px !important ;
}

.list-link {
  > a {
    color: $gray-600 !important ;
    padding: 4px !important ;

    &:hover {
      color: $gray-900 !important ;
    }
  }
}

// User block
.user-block {
  float: left !important ;

  img {
    float: left !important ;
    height: 40px !important ;
    width: 40px !important ;
  }

  .username,
  .description,
  .comment {
    display: block !important ;
    margin-left: 50px !important ;
  }

  .username {
    font-size: 16px !important ;
    font-weight: 600 !important ;
    margin-top: -1px !important ;
  }

  .description {
    color: $gray-600 !important ;
    font-size: 13px !important ;
    margin-top: -3px !important ;
  }

  &.user-block-sm {
    img {
      width: $img-size-sm !important ;
      height: $img-size-sm !important ;
    }

    .username,
    .description,
    .comment {
      margin-left: 40px !important ;
    }

    .username {
      font-size: 14px !important ;
    }
  }
}

// Image sizes
.img-sm,
.img-md,
.img-lg {
  float: left !important ;
}

.img-sm {
  height: $img-size-sm !important ;
  width: $img-size-sm !important ;

  + .img-push {
    margin-left: $img-size-sm + $img-size-push !important ;
  }
}

.img-md {
  width: $img-size-md !important ;
  height: $img-size-md !important ;

  + .img-push {
    margin-left: $img-size-md + $img-size-push !important ;
  }
}

.img-lg {
  width: $img-size-lg !important ;
  height: $img-size-lg !important ;

  + .img-push {
    margin-left: $img-size-lg + $img-size-push !important ;
  }
}

// Image bordered
.img-bordered {
  border: 3px solid $gray-500 !important ;
  padding: 3px !important ;
}

.img-bordered-sm {
  border: 2px solid $gray-500 !important ;
  padding: 2px !important ;
}

// Rounded and Circle Images
.img-rounded {
  @include border-radius($border-radius) !important ;
}

.img-circle {
  @include border-radius(50%) !important ;
}

// Image sizes
.img-size-64,
.img-size-50,
.img-size-32 {
  height: auto !important ;
}

.img-size-64 {
  width: 64px !important ;
}

.img-size-50 {
  width: 50px !important ;
}

.img-size-32 {
  width: 32px !important ;
}

// Block sizes
.size-32,
.size-40,
.size-50 {
  display: block !important ;
  text-align: center !important ;
}

.size-32 {
  height: 32px !important ;
  line-height: 32px !important ;
  width: 32px !important ;
}

.size-40 {
  height: 40px !important ;
  line-height: 40px !important ;
  width: 40px !important ;
}

.size-50 {
  height: 50px !important ;
  line-height: 50px !important ;
  width: 50px !important ;
}

// General attachemnt block
.attachment-block {
  background-color: $gray-100 !important ;
  border: 1px solid $card-border-color !important ;
  margin-bottom: 10px !important ;
  padding: 5px !important ;

  .attachment-img {
    float: left !important ;
    height: auto !important ;
    max-height: 100px !important ;
    max-width: 100px !important ;
  }

  .attachment-pushed {
    margin-left: 110px !important ;
  }

  .attachment-heading {
    margin: 0 !important ;
  }

  .attachment-text {
    color: $gray-700 !important ;
  }
}

// Overlays for Card, InfoBox & SmallBox
.card,
.overlay-wrapper,
.info-box,
.small-box {
  // Box overlay for LOADING STATE effect
  > .overlay,
  > .loading-img {
    height: 100% !important ;
    left: 0 !important ;
    position: absolute !important ;
    top: 0 !important ;
    width: 100% !important ;
  }

  .overlay {
    @include border-radius($border-radius) !important ;
    align-items: center !important ;
    background-color: rgba($white, .7) !important ;
    display: flex !important ;
    justify-content: center !important ;
    z-index: 50 !important ;

    > .fa,
    > .fas,
    > .far,
    > .fab,
    > .fal,
    > .fad,
    > .svg-inline--fa,
    > .ion {
      color: $gray-800 !important ;
    }

    &.dark {
      background-color: rgba($black, .5) !important ;

      > .fa,
      > .fas,
      > .far,
      > .fab,
      > .fal,
      > .fad,
      > .svg-inline--fa,
      > .ion {
        color: $gray-400 !important ;
      }
    }
  }
}

.tab-pane {
  // Box overlay for LOADING STATE effect on Tab Panels
  > .overlay-wrapper {
    position: relative !important ;
    > .overlay {
      border-top-left-radius: 0 !important ;
      border-top-right-radius: 0 !important ;
      flex-direction: column !important ;
      margin-top: -$card-spacer-x !important ;
      margin-left: -$card-spacer-x !important ;
      height: calc(100% + 2 * #{$card-spacer-x}) !important ;
      width: calc(100% + 2 * #{$card-spacer-x}) !important ;

      &.dark {
        color: $white !important ;
      }
    }
  }
}

// Ribbon
.ribbon-wrapper {
  height: $ribbon-wrapper-size !important ;
  overflow: hidden !important ;
  position: absolute !important ;
  right: -2px !important ;
  top: -2px !important ;
  width: $ribbon-wrapper-size !important ;
  z-index: 10 !important ;

  &.ribbon-lg {
    height: $ribbon-lg-wrapper-size !important ;
    width: $ribbon-lg-wrapper-size !important ;

    .ribbon {
      right: $ribbon-lg-right !important ;
      top: $ribbon-lg-top !important ;
      width: $ribbon-lg-width !important ;
    }
  }

  &.ribbon-xl {
    height: $ribbon-xl-wrapper-size !important ;
    width: $ribbon-xl-wrapper-size !important ;

    .ribbon {
      right: $ribbon-xl-right !important ;
      top: $ribbon-xl-top !important ;
      width: $ribbon-xl-width !important ;
    }
  }

  .ribbon {
    box-shadow: 0 0 $ribbon-border-size rgba($black, .3) !important ;
    font-size: $ribbon-font-size !important ;
    line-height: $ribbon-line-height !important ;
    padding: $ribbon-padding !important ;
    position: relative !important ;
    right: $ribbon-right !important ;
    text-align: center !important ;
    text-shadow: 0 -1px 0 rgba($black, .4) !important ;
    text-transform: uppercase !important ;
    top: $ribbon-top !important ;
    transform: rotate(45deg) !important ;
    width: $ribbon-width !important ;

    &::before,
    &::after {
      border-left: $ribbon-border-size solid transparent !important ;
      border-right: $ribbon-border-size solid transparent !important ;
      border-top: $ribbon-border-size solid #9e9e9e !important ;
      bottom: -$ribbon-border-size !important ;
      content: "" !important ;
      position: absolute !important ;
    }

    &::before {
      left: 0 !important ;
    }

    &::after {
      right: 0 !important ;
    }
  }
}

// Scroll To Top
.back-to-top {
  bottom: 1.25rem !important ;
  position: fixed !important ;
  right: 1.25rem !important ;
  z-index: $zindex-control-sidebar + 1 !important ;

  &:focus {
    box-shadow: none !important ;
  }
}

// Pre
pre {
  padding: .75rem !important ;
}

// Blockquotes styles
blockquote {
  background-color: $white !important ;
  border-left: .7rem solid $primary !important ;
  margin: 1.5em .7rem !important ;
  padding: .5em .7rem !important ;

  .box & {
    background-color: $gray-200 !important ;
  }

  p:last-child {
    margin-bottom: 0 !important ;
  }

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    color: $primary !important ;
    font-size: 1.25rem !important ;
    font-weight: 600 !important ;
  }

  @each $color, $value in $theme-colors {
    &.quote-#{$color} {
      border-color: $value !important ;

      h1,
      h2,
      h3,
      h4,
      h5,
      h6 {
        color: $value !important ;
      }
    }
  }

  @each $color, $value in $colors {
    &.quote-#{$color} {
      border-color: $value !important ;

      h1,
      h2,
      h3,
      h4,
      h5,
      h6 {
        color: $value !important ;
      }
    }
  }
}


// Tab Custom Content

.tab-custom-content {
  border-top: $nav-tabs-border-width solid $nav-tabs-border-color !important ;
  margin-top: .5rem !important ;
  padding-top: .5rem !important ;
}

.nav + .tab-custom-content {
  border-top: none !important ;
  border-bottom: $nav-tabs-border-width solid $nav-tabs-border-color !important ;
  margin-top: 0 !important ;
  margin-bottom: .5rem !important ;
  padding-bottom: .5rem !important ;
}


// Badge BTN Style
.badge-btn {
  border-radius: $button-border-radius-xs !important ;
  font-size: $button-font-size-xs !important ;
  font-weight: 400 !important ;
  padding: $button-padding-y-xs * 2 $button-padding-x-xs * 2 !important ;
}

.badge-btn.badge-pill {
  padding: .375rem .6rem !important ;
}

@include dark-mode () {
  a:not(.btn):hover {
    color: lighten($link-color, 10%) !important ;
  }
  .attachment-block {
    background-color: lighten($dark, 3.75%) !important ;

    .attachment-text {
      color: $gray-400 !important ;
    }
  }
  blockquote {
    background-color: lighten($dark, 5%) !important ;

    @each $color, $value in $theme-colors {
      &.quote-#{$color} {
        border-color: $value !important ;

        h1,
        h2,
        h3,
        h4,
        h5,
        h6 {
          color: $value !important ;
        }
      }
    }

    @each $color, $value in $colors {
      &.quote-#{$color} {
        border-color: $value !important ;

        h1,
        h2,
        h3,
        h4,
        h5,
        h6 {
          color: $value !important ;
        }
      }
    }
  }
  .close,
  .mailbox-attachment-close {
    color: $gray-500 !important ;
    text-shadow: 0 1px 0 $gray-700 !important ;
  }
  .tab-custom-content {
    border-color: $gray-600 !important ;
  }
  .list-group-item {
    background-color: $dark !important ;
    border-color: $gray-600 !important ;
  }
}
