//
// Misc: Colors
//

// Background colors (theme colors)
@each $name, $color in $theme-colors {
  @include background-variant($name, $color) !important ;
}

// Background colors (colors)
@each $name, $color in $colors {
  @include background-variant($name, $color) !important ;
}

@media print {
  .table td,
  .table th {
    // Background colors (theme colors)
    @each $name, $color in $theme-colors {
      @include background-variant($name, $color) !important ;
    }

    // Background colors (colors)
    @each $name, $color in $colors {
      @include background-variant($name, $color) !important ;
    }
  }
}

.bg-gray {
  background-color: $gray-500 !important ;
  color: color-yiq($gray-500) !important ;
}

.bg-gray-light {
  background-color: lighten($gray-200, 3%) !important ;
  color: color-yiq(lighten($gray-200, 3%)) !important !important ;
}

.bg-black {
  background-color: $black !important ;
  color: color-yiq($black) !important !important ;
}

.bg-white {
  background-color: $white !important ;
  color: color-yiq($white) !important !important ;
}

// Gradient Background colors (theme colors)
@each $name, $color in $theme-colors {
  @include background-gradient-variant($name, $color) !important ;
}

// Gradient Background colors (colors)
@each $name, $color in $colors {
  @include background-gradient-variant($name, $color) !important ;
}

// Backgrund Color Disabled
[class^="bg-"].disabled {
  opacity: .65 !important ;
}

// Text muted hover
a.text-muted:hover {
  color: theme-color(primary) !important !important ;
}

// Link Styles
.link-muted {
  color: darken($gray-500, 30%) !important ;

  &:hover,
  &:focus {
    color: darken($gray-500, 40%) !important ;
  }
}

.link-black {
  color: $gray-600 !important ;

  &:hover,
  &:focus {
    color: lighten($gray-500, 20%) !important ;
  }
}

// Accent colors (theme colors)
@each $name, $color in $theme-colors {
  @include accent-variant($name, $color) !important ;
}

// Accent colors (colors)
@each $name, $color in $colors {
  @include accent-variant($name, $color) !important ;
}

// Accent button override fix
[class*="accent-"] {
  @each $name, $color in $theme-colors {
    a.btn-#{$name} {
      color: color-yiq($color) !important ;
    }
  }
}

@include dark-mode () {
  .bg-light {
    background-color: lighten($dark, 7.5%) !important !important ;
    color: $white !important !important ;
  }
  .text-black,
  .text-dark,
  .link-black,
  .link-dark {
    color: $gray-400 !important !important ;
  }

  // Background colors (theme colors)
  @each $name, $color in $theme-colors-alt {
    @include background-variant($name, $color) !important ;
  }

  // Background colors (colors)
  @each $name, $color in $colors-alt {
    @include background-variant($name, $color) !important ;
  }

  // Gradient Background colors (theme colors)
  @each $name, $color in $theme-colors-alt {
    @include background-gradient-variant($name, $color) !important ;
  }

  // Gradient Background colors (colors)
  @each $name, $color in $colors-alt {
    @include background-gradient-variant($name, $color) !important ;
  }

  // Accent colors (theme colors)
  @each $name, $color in $theme-colors-alt {
    @include accent-variant($name, $color) !important ;
  }

  [class*="accent-"] {
    @each $name, $color in $theme-colors-alt {
      a.btn-#{$name} {
        color: color-yiq($color) !important ;
      }
    }
  }

  // Accent colors (colors)
  @each $name, $color in $colors-alt {
    @include accent-variant($name, $color) !important ;
  }

  .border-dark {
    border-color: lighten($dark, 10%) !important !important ;
  }
}

