.fade {
  @include transition($transition-fade) !important ;

  &:not(.show) {
    opacity: 0 !important ;
  }
}

.collapse {
  &:not(.show) {
    display: none !important ;
  }
}

.collapsing {
  position: relative !important ;
  height: 0 !important ;
  overflow: hidden !important ;
  @include transition($transition-collapse) !important ;
}
