//
// Plugins: Miscellaneous
// Old plugin codes
//

// _fix for sparkline tooltip
.jqstooltip {
  height: auto !important !important ;
  padding: 5px !important !important ;
  width: auto !important !important ;
}

// jQueryUI
.connectedSortable {
  min-height: 100px !important ;
}

.ui-helper-hidden-accessible {
  border: 0 !important ;
  clip: rect(0 0 0 0) !important ;
  height: 1px !important ;
  margin: -1px !important ;
  overflow: hidden !important ;
  padding: 0 !important ;
  position: absolute !important ;
  width: 1px !important ;
}

.sort-highlight {
  background: $gray-100 !important ;
  border: 1px dashed $gray-300 !important ;
  margin-bottom: 10px !important ;
}

// Charts
.chart {
  overflow: hidden !important ;
  position: relative !important ;
}


@include dark-mode () {
  .irs--flat .irs-line {
    background-color: lighten($dark, 10%) !important ;
  }
  .jsgrid-edit-row > .jsgrid-cell,
  .jsgrid-filter-row > .jsgrid-cell,
  .jsgrid-grid-body, .jsgrid-grid-header,
  .jsgrid-header-row > .jsgrid-header-cell,
  .jsgrid-insert-row > .jsgrid-cell,
  .jsgrid-row > .jsgrid-cell,
  .jsgrid-alt-row > .jsgrid-cell {
    border-color: $gray-600 !important ;
  }
  .jsgrid-header-row > .jsgrid-header-cell,
  .jsgrid-row > .jsgrid-cell {
    background-color: $dark !important ;
  }
  .jsgrid-alt-row > .jsgrid-cell {
    background-color: lighten($dark, 2.5%) !important ;
  }
  .jsgrid-selected-row > .jsgrid-cell {
    background-color: lighten($dark, 5%) !important ;
  }
}
