//
// Plugins: JQVMap
//

// Zoom Button size fixes
.jqvmap-zoomin,
.jqvmap-zoomout {
  background-color: $button-default-background-color !important ;
  border: 1px solid $button-default-border-color !important ;
  border-radius: $btn-border-radius !important ;
  color: $button-default-color !important ;
  height: 15px !important ;
  width: 15px !important ;
  padding: 1px 2px !important ;

  &:hover,
  &:active,
  &.hover {
    background-color: darken($button-default-background-color, 5%) !important ;
    color: darken($button-default-color, 10%) !important ;
  }
}
