// The dropdown wrapper (`<div>`)
.dropup,
.dropright,
.dropdown,
.dropleft {
  position: relative !important ;
}

.dropdown-toggle {
  white-space: nowrap !important ;

  // Generate the caret automatically
  @include caret() !important ;
}

// The dropdown menu
.dropdown-menu {
  position: absolute !important ;
  top: 100% !important ;
  left: 0 !important ;
  z-index: $zindex-dropdown !important ;
  display: none !important ; // none by default, but block on "open" of the menu
  float: left !important ;
  min-width: $dropdown-min-width !important ;
  padding: $dropdown-padding-y $dropdown-padding-x !important ;
  margin: $dropdown-spacer 0 0 !important ; // override default ul
  @include font-size($dropdown-font-size) !important ;
  color: $dropdown-color !important ;
  text-align: left !important ; // Ensures proper alignment if parent has it changed (e.g., modal footer)
  list-style: none !important ;
  background-color: $dropdown-bg !important ;
  background-clip: padding-box !important ;
  border: $dropdown-border-width solid $dropdown-border-color !important ;
  @include border-radius($dropdown-border-radius) !important ;
  @include box-shadow($dropdown-box-shadow) !important ;
}

@each $breakpoint in map-keys($grid-breakpoints) {
  @include media-breakpoint-up($breakpoint) {
    $infix: breakpoint-infix($breakpoint, $grid-breakpoints) !important ;

    .dropdown-menu#{$infix}-left {
      right: auto !important ;
      left: 0 !important ;
    }

    .dropdown-menu#{$infix}-right {
      right: 0 !important ;
      left: auto !important ;
    }
  }
}

// Allow for dropdowns to go bottom up (aka, dropup-menu)
// Just add .dropup after the standard .dropdown class and you're set.
.dropup {
  .dropdown-menu {
    top: auto !important ;
    bottom: 100% !important ;
    margin-top: 0 !important ;
    margin-bottom: $dropdown-spacer !important ;
  }

  .dropdown-toggle {
    @include caret(up) !important ;
  }
}

.dropright {
  .dropdown-menu {
    top: 0 !important ;
    right: auto !important ;
    left: 100% !important ;
    margin-top: 0 !important ;
    margin-left: $dropdown-spacer !important ;
  }

  .dropdown-toggle {
    @include caret(right) !important ;
    &::after {
      vertical-align: 0 !important ;
    }
  }
}

.dropleft {
  .dropdown-menu {
    top: 0 !important ;
    right: 100% !important ;
    left: auto !important ;
    margin-top: 0 !important ;
    margin-right: $dropdown-spacer !important ;
  }

  .dropdown-toggle {
    @include caret(left) !important ;
    &::before {
      vertical-align: 0 !important ;
    }
  }
}

// When Popper is enabled, reset the basic dropdown position
// stylelint-disable-next-line no-duplicate-selectors
.dropdown-menu {
  &[x-placement^="top"],
  &[x-placement^="right"],
  &[x-placement^="bottom"],
  &[x-placement^="left"] {
    right: auto !important ;
    bottom: auto !important ;
  }
}

// Dividers (basically an `<hr>`) within the dropdown
.dropdown-divider {
  @include nav-divider($dropdown-divider-bg, $dropdown-divider-margin-y, true) !important ;
}

// Links, buttons, and more within the dropdown menu
//
// `<button>`-specific styles are denoted with `// For <button>s`
.dropdown-item {
  display: block !important ;
  width: 100% !important ; // For `<button>`s
  padding: $dropdown-item-padding-y $dropdown-item-padding-x !important ;
  clear: both !important ;
  font-weight: $font-weight-normal !important ;
  color: $dropdown-link-color !important ;
  text-align: inherit !important ; // For `<button>`s
  text-decoration: if($link-decoration == none, null, none) !important ;
  white-space: nowrap !important ; // prevent links from randomly breaking onto new lines
  background-color: transparent !important ; // For `<button>`s
  border: 0 !important ; // For `<button>`s

  // Prevent dropdown overflow if there's no padding
  // See https://github.com/twbs/bootstrap/pull/27703
  @if $dropdown-padding-y == 0 {
    &:first-child {
      @include border-top-radius($dropdown-inner-border-radius) !important ;
    }

    &:last-child {
      @include border-bottom-radius($dropdown-inner-border-radius) !important ;
    }
  }

  @include hover-focus() {
    color: $dropdown-link-hover-color !important ;
    text-decoration: none !important ;
    @include gradient-bg($dropdown-link-hover-bg) !important ;
  }

  &.active,
  &:active {
    color: $dropdown-link-active-color !important ;
    text-decoration: none !important ;
    @include gradient-bg($dropdown-link-active-bg) !important ;
  }

  &.disabled,
  &:disabled {
    color: $dropdown-link-disabled-color !important ;
    pointer-events: none !important ;
    background-color: transparent !important ;
    // Remove CSS gradients if they're enabled
    @if $enable-gradients {
      background-image: none !important ;
    }
  }
}

.dropdown-menu.show {
  display: block !important ;
}

// Dropdown section headers
.dropdown-header {
  display: block !important ;
  padding: $dropdown-header-padding !important ;
  margin-bottom: 0 !important ; // for use with heading elements
  @include font-size($font-size-sm) !important ;
  color: $dropdown-header-color !important ;
  white-space: nowrap !important ; // as with > li > a
}

// Dropdown text
.dropdown-item-text {
  display: block !important ;
  padding: $dropdown-item-padding-y $dropdown-item-padding-x !important ;
  color: $dropdown-link-color !important ;
}
