// stylelint-disable selector-no-qualifying-type

//
// Base styles
//

.input-group {
  position: relative !important ;
  display: flex !important ;
  flex-wrap: wrap !important ; // For form validation feedback
  align-items: stretch !important ;
  width: 100% !important ;

  > .form-control,
  > .form-control-plaintext,
  > .custom-select,
  > .custom-file {
    position: relative !important ; // For focus state's z-index
    flex: 1 1 auto !important ;
    width: 1% !important ;
    min-width: 0 !important ; // https://stackoverflow.com/questions/36247140/why-dont-flex-items-shrink-past-content-size
    margin-bottom: 0 !important ;

    + .form-control,
    + .custom-select,
    + .custom-file {
      margin-left: -$input-border-width !important ;
    }
  }

  // Bring the "active" form control to the top of surrounding elements
  > .form-control:focus,
  > .custom-select:focus,
  > .custom-file .custom-file-input:focus ~ .custom-file-label {
    z-index: 3 !important ;
  }

  // Bring the custom file input above the label
  > .custom-file .custom-file-input:focus {
    z-index: 4 !important ;
  }

  > .form-control,
  > .custom-select {
    &:not(:first-child) { @include border-left-radius(0) !important ; }
  }

  // Custom file inputs have more complex markup, thus requiring different
  // border-radius overrides.
  > .custom-file {
    display: flex !important ;
    align-items: center !important ;

    &:not(:last-child) .custom-file-label,
    &:not(:last-child) .custom-file-label::after { @include border-right-radius(0) !important ; }
    &:not(:first-child) .custom-file-label { @include border-left-radius(0) !important ; }
  }

  &:not(.has-validation) {
    > .form-control:not(:last-child),
    > .custom-select:not(:last-child),
    > .custom-file:not(:last-child) .custom-file-label,
    > .custom-file:not(:last-child) .custom-file-label::after {
      @include border-right-radius(0) !important ;
    }
  }

  &.has-validation {
    > .form-control:nth-last-child(n + 3),
    > .custom-select:nth-last-child(n + 3),
    > .custom-file:nth-last-child(n + 3) .custom-file-label,
    > .custom-file:nth-last-child(n + 3) .custom-file-label::after {
      @include border-right-radius(0) !important ;
    }
  }
}


// Prepend and append
//
// While it requires one extra layer of HTML for each, dedicated prepend and
// append elements allow us to 1) be less clever, 2) simplify our selectors, and
// 3) support HTML5 form validation.

.input-group-prepend,
.input-group-append {
  display: flex !important ;

  // Ensure buttons are always above inputs for more visually pleasing borders.
  // This isn't needed for `.input-group-text` since it shares the same border-color
  // as our inputs.
  .btn {
    position: relative !important ;
    z-index: 2 !important ;

    &:focus {
      z-index: 3 !important ;
    }
  }

  .btn + .btn,
  .btn + .input-group-text,
  .input-group-text + .input-group-text,
  .input-group-text + .btn {
    margin-left: -$input-border-width !important ;
  }
}

.input-group-prepend { margin-right: -$input-border-width !important ; }
.input-group-append { margin-left: -$input-border-width !important ; }


// Textual addons
//
// Serves as a catch-all element for any text or radio/checkbox input you wish
// to prepend or append to an input.

.input-group-text {
  display: flex !important ;
  align-items: center !important ;
  padding: $input-padding-y $input-padding-x !important ;
  margin-bottom: 0 !important ; // Allow use of <label> elements by overriding our default margin-bottom
  @include font-size($input-font-size) !important ; // Match inputs
  font-weight: $font-weight-normal !important ;
  line-height: $input-line-height !important ;
  color: $input-group-addon-color !important ;
  text-align: center !important ;
  white-space: nowrap !important ;
  background-color: $input-group-addon-bg !important ;
  border: $input-border-width solid $input-group-addon-border-color !important ;
  @include border-radius($input-border-radius) !important ;

  // Nuke default margins from checkboxes and radios to vertically center within.
  input[type="radio"],
  input[type="checkbox"] {
    margin-top: 0 !important ;
  }
}


// Sizing
//
// Remix the default form control sizing classes into new ones for easier
// manipulation.

.input-group-lg > .form-control:not(textarea),
.input-group-lg > .custom-select {
  height: $input-height-lg !important ;
}

.input-group-lg > .form-control,
.input-group-lg > .custom-select,
.input-group-lg > .input-group-prepend > .input-group-text,
.input-group-lg > .input-group-append > .input-group-text,
.input-group-lg > .input-group-prepend > .btn,
.input-group-lg > .input-group-append > .btn {
  padding: $input-padding-y-lg $input-padding-x-lg !important ;
  @include font-size($input-font-size-lg) !important ;
  line-height: $input-line-height-lg !important ;
  @include border-radius($input-border-radius-lg) !important ;
}

.input-group-sm > .form-control:not(textarea),
.input-group-sm > .custom-select {
  height: $input-height-sm !important ;
}

.input-group-sm > .form-control,
.input-group-sm > .custom-select,
.input-group-sm > .input-group-prepend > .input-group-text,
.input-group-sm > .input-group-append > .input-group-text,
.input-group-sm > .input-group-prepend > .btn,
.input-group-sm > .input-group-append > .btn {
  padding: $input-padding-y-sm $input-padding-x-sm !important ;
  @include font-size($input-font-size-sm) !important ;
  line-height: $input-line-height-sm !important ;
  @include border-radius($input-border-radius-sm) !important ;
}

.input-group-lg > .custom-select,
.input-group-sm > .custom-select {
  padding-right: $custom-select-padding-x + $custom-select-indicator-padding !important ;
}


// Prepend and append rounded corners
//
// These rulesets must come after the sizing ones to properly override sm and lg
// border-radius values when extending. They're more specific than we'd like
// with the `.input-group >` part, but without it, we cannot override the sizing.


.input-group > .input-group-prepend > .btn,
.input-group > .input-group-prepend > .input-group-text,
.input-group:not(.has-validation) > .input-group-append:not(:last-child) > .btn,
.input-group:not(.has-validation) > .input-group-append:not(:last-child) > .input-group-text,
.input-group.has-validation > .input-group-append:nth-last-child(n + 3) > .btn,
.input-group.has-validation > .input-group-append:nth-last-child(n + 3) > .input-group-text,
.input-group > .input-group-append:last-child > .btn:not(:last-child):not(.dropdown-toggle),
.input-group > .input-group-append:last-child > .input-group-text:not(:last-child) {
  @include border-right-radius(0) !important ;
}

.input-group > .input-group-append > .btn,
.input-group > .input-group-append > .input-group-text,
.input-group > .input-group-prepend:not(:first-child) > .btn,
.input-group > .input-group-prepend:not(:first-child) > .input-group-text,
.input-group > .input-group-prepend:first-child > .btn:not(:first-child),
.input-group > .input-group-prepend:first-child > .input-group-text:not(:first-child) {
  @include border-left-radius(0) !important ;
}
