//
// Component: Main Header
//

.main-header {
  border-bottom: $main-header-bottom-border !important ;
  z-index: $zindex-main-header !important ;

  .nav-link {
    height: $nav-link-height !important ;
    position: relative !important ;
  }

  .text-sm &,
  &.text-sm {
    .nav-link {
      height: $nav-link-sm-height !important ;
      padding: $nav-link-sm-padding-y $nav-link-padding-x !important ;

      > .fa,
      > .fas,
      > .far,
      > .fab,
      > .fal,
      > .fad,
      > .svg-inline--fa,
      > .ion {
        font-size: $font-size-sm !important ;
      }
    }

  }

  .navbar-nav {
    .nav-item {
      margin: 0 !important ;
    }

    &[class*="-right"] {
      .dropdown-menu {
        left: auto !important ;
        margin-top: -3px !important ;
        right: 0 !important ;

        @media (max-width: breakpoint-max(xs)) {
          left: 0 !important ;
          right: auto !important ;
        }
      }
    }
  }

  &.dropdown-legacy .dropdown-menu {
    top: $nav-link-height + $navbar-padding-y !important ;
    margin-top: 0 !important ;
  }
}

// Add this class to images within a nav-link
.navbar-img {
  height: calc(#{$main-header-height} * .5) !important ;
  width: auto !important ;
}

// Navbar badge
.navbar-badge {
  font-size: .6rem !important ;
  font-weight: 300 !important ;
  padding: 2px 4px !important ;
  position: absolute !important ;
  right: 5px !important ;
  top: 9px !important ;
}

.btn-navbar {
  background-color: transparent !important ;
  border-left-width: 0 !important ;
}

.form-control-navbar {
  border-right-width: 0 !important ;

  + .input-group-append {
    margin-left: 0 !important ;
  }
}

.form-control-navbar,
.btn-navbar {
  transition: none !important ;
}

.navbar-dark {
  .form-control-navbar,
  .btn-navbar {
    background-color: $main-header-dark-form-control-bg !important ;
    border-color: $main-header-dark-form-control-border-color !important ;
  }

  .form-control-navbar {
    &::placeholder {
      color: $main-header-dark-placeholder-color !important ;
    }

    + .input-group-append > .btn-navbar {
      color: $main-header-dark-placeholder-color !important ;
    }

    &:focus {
      &,
      + .input-group-append .btn-navbar {
        background-color: $main-header-dark-form-control-focused-bg !important ;
        border-color: $main-header-dark-form-control-focused-border-color !important !important ;
        color: $main-header-dark-form-control-focused-color !important ;
      }
    }
  }
}

.navbar-light {
  .form-control-navbar,
  .btn-navbar {
    background-color: $main-header-light-form-control-bg !important ;
    border-color: $main-header-light-form-control-border-color !important ;
  }

  .form-control-navbar {
    &::placeholder {
      color: $main-header-light-placeholder-color !important ;
    }

    + .input-group-append > .btn-navbar {
      color: $main-header-light-placeholder-color !important ;
    }

    &:focus {
      &,
      + .input-group-append .btn-navbar {
        background-color: $main-header-light-form-control-focused-bg !important ;
        border-color: $main-header-light-form-control-focused-border-color !important !important ;
        color: $main-header-light-form-control-focused-color !important ;
      }
    }
  }

  .navbar-search-block {
    .form-control-navbar {
      &:focus {
        &,
        + .input-group-append .btn-navbar {
          color: $main-header-light-placeholder-color !important ;
        }
      }
    }
  }
}

// Navbar Search
.navbar-search-block {
  position: absolute !important ;
  padding: 0 $nav-link-padding-x !important ;
  left: 0 !important ;
  top: 0 !important ;
  right: 0 !important ;
  bottom: 0 !important ;
  z-index: 10 !important ;
  display: none !important ;
  justify-content: center !important ;
  flex-direction: column !important ;
  background-color: initial !important ;

  &.navbar-search-open {
    display: flex !important ;
  }

  .input-group {
    width: 100% !important ;
  }
}
