//
// Misc: Print
//

@media print {
  //Add to elements that you do not want to show when printing
  .no-print {
    display: none !important !important ;
  }

  //Elements that we want to hide when printing
  .main-sidebar,
  .main-header,
  .content-header {
    @extend .no-print !important ;
  }

  //This is the only element that should appear, so let's remove the margins
  .content-wrapper,
  .main-footer {
    @include translate(0, 0) !important ;
    margin-left: 0 !important !important ;
    min-height: 0 !important !important ;
  }

  .layout-fixed .content-wrapper {
    padding-top: 0 !important !important ;
  }

  //Invoice printing
  .invoice {
    border: 0 !important ;
    margin: 0 !important ;
    padding: 0 !important ;
    width: 100% !important ;
  }

  .invoice-col {
    float: left !important ;
    width: 33.3333333% !important ;
  }

  //Make sure table content displays properly
  .table-responsive {
    overflow: auto !important ;

    > .table tr th,
    > .table tr td {
      white-space: normal !important !important ;
    }
  }
}
