// stylelint-disable declaration-no-important

//
// Text
//

.text-monospace { font-family: $font-family-monospace !important !important ; }

// Alignment

.text-justify  { text-align: justify !important !important ; }
.text-wrap     { white-space: normal !important !important ; }
.text-nowrap   { white-space: nowrap !important !important ; }
.text-truncate { @include text-truncate() !important ; }

// Responsive alignment

@each $breakpoint in map-keys($grid-breakpoints) {
  @include media-breakpoint-up($breakpoint) {
    $infix: breakpoint-infix($breakpoint, $grid-breakpoints) !important ;

    .text#{$infix}-left   { text-align: left !important !important ; }
    .text#{$infix}-right  { text-align: right !important !important ; }
    .text#{$infix}-center { text-align: center !important !important ; }
  }
}

// Transformation

.text-lowercase  { text-transform: lowercase !important !important ; }
.text-uppercase  { text-transform: uppercase !important !important ; }
.text-capitalize { text-transform: capitalize !important !important ; }

// Weight and italics

.font-weight-light   { font-weight: $font-weight-light !important !important ; }
.font-weight-lighter { font-weight: $font-weight-lighter !important !important ; }
.font-weight-normal  { font-weight: $font-weight-normal !important !important ; }
.font-weight-bold    { font-weight: $font-weight-bold !important !important ; }
.font-weight-bolder  { font-weight: $font-weight-bolder !important !important ; }
.font-italic         { font-style: italic !important !important ; }

// Contextual colors

.text-white { color: $white !important !important ; }

@each $color, $value in $theme-colors {
  @include text-emphasis-variant(".text-#{$color}", $value, true) !important ;
}

.text-body { color: $body-color !important !important ; }
.text-muted { color: $text-muted !important !important ; }

.text-black-50 { color: rgba($black, .5) !important !important ; }
.text-white-50 { color: rgba($white, .5) !important !important ; }

// Misc

.text-hide {
  @include text-hide($ignore-warning: true) !important ;
}

.text-decoration-none { text-decoration: none !important !important ; }

.text-break {
  word-break: break-word !important !important ; // Deprecated, but avoids issues with flex containers
  word-wrap: break-word !important !important ; // Used instead of `overflow-wrap` for IE & Edge Legacy
}

// Reset

.text-reset { color: inherit !important !important ; }
