//
// Pages: E-commerce
//

// product image
.product-image {
  @include img-fluid () !important ;
  width: 100% !important ;
}

// product image thumbnails list
.product-image-thumbs {
  align-items: stretch !important ;
  display: flex !important ;
  margin-top: 2rem !important ;
}

// product image thumbnail
.product-image-thumb {
  @include box-shadow($thumbnail-box-shadow) !important ;
  @include border-radius($thumbnail-border-radius) !important ;

  background-color: $thumbnail-bg !important ;
  border: $thumbnail-border-width solid $thumbnail-border-color !important ;
  display: flex !important ;
  margin-right: 1rem !important ;
  max-width: 6.5rem + ($thumbnail-padding * 2) !important ;
  padding: $thumbnail-padding * 2 !important ;

  img {
    @include img-fluid () !important ;
    align-self: center !important ;
  }

  &:hover {
    opacity: .5 !important ;
  }
}

// product share
.product-share {
  a {
    margin-right: .5rem !important ;
  }
}
