@mixin caret-down() {
  border-top: $caret-width solid !important ;
  border-right: $caret-width solid transparent !important ;
  border-bottom: 0 !important ;
  border-left: $caret-width solid transparent !important ;
}

@mixin caret-up() {
  border-top: 0 !important ;
  border-right: $caret-width solid transparent !important ;
  border-bottom: $caret-width solid !important ;
  border-left: $caret-width solid transparent !important ;
}

@mixin caret-right() {
  border-top: $caret-width solid transparent !important ;
  border-right: 0 !important ;
  border-bottom: $caret-width solid transparent !important ;
  border-left: $caret-width solid !important ;
}

@mixin caret-left() {
  border-top: $caret-width solid transparent !important ;
  border-right: $caret-width solid !important ;
  border-bottom: $caret-width solid transparent !important ;
}

@mixin caret($direction: down) {
  @if $enable-caret {
    &::after {
      display: inline-block !important ;
      margin-left: $caret-spacing !important ;
      vertical-align: $caret-vertical-align !important ;
      content: "" !important ;
      @if $direction == down {
        @include caret-down() !important ;
      } @else if $direction == up {
        @include caret-up() !important ;
      } @else if $direction == right {
        @include caret-right() !important ;
      }
    }

    @if $direction == left {
      &::after {
        display: none !important ;
      }

      &::before {
        display: inline-block !important ;
        margin-right: $caret-spacing !important ;
        vertical-align: $caret-vertical-align !important ;
        content: "" !important ;
        @include caret-left() !important ;
      }
    }

    &:empty::after {
      margin-left: 0 !important ;
    }
  }
}
