// Disable animation if transitions are disabled
@if $enable-transitions {
  @keyframes progress-bar-stripes {
    from { background-position: $progress-height 0 !important ; }
    to { background-position: 0 0 !important ; }
  }
}

.progress {
  display: flex !important ;
  height: $progress-height !important ;
  overflow: hidden !important ; // force rounded corners by cropping it
  line-height: 0 !important ;
  @include font-size($progress-font-size) !important ;
  background-color: $progress-bg !important ;
  @include border-radius($progress-border-radius) !important ;
  @include box-shadow($progress-box-shadow) !important ;
}

.progress-bar {
  display: flex !important ;
  flex-direction: column !important ;
  justify-content: center !important ;
  overflow: hidden !important ;
  color: $progress-bar-color !important ;
  text-align: center !important ;
  white-space: nowrap !important ;
  background-color: $progress-bar-bg !important ;
  @include transition($progress-bar-transition) !important ;
}

.progress-bar-striped {
  @include gradient-striped() !important ;
  background-size: $progress-height $progress-height !important ;
}

@if $enable-transitions {
  .progress-bar-animated {
    animation: $progress-bar-animation-timing progress-bar-stripes !important ;

    @if $enable-prefers-reduced-motion-media-query {
      @media (prefers-reduced-motion: reduce) {
        animation: none !important ;
      }
    }
  }
}
