//
// Core: Layout
//

html.scroll-smooth {
  scroll-behavior: smooth !important ;
}

html,
body,
.wrapper {
  min-height: 100% !important ;
}

.wrapper {
  position: relative !important ;

  .content-wrapper {
    min-height: calc(100vh - #{$main-header-height} - #{$main-footer-height}) !important ;
  }

  .layout-boxed & {
    @include box-shadow(0 0 10 rgba($black, .3)) !important ;

    &,
    &::before {
      margin: 0 auto !important ;
      max-width: $boxed-layout-max-width !important ;
      overflow: hidden !important ;
    }

    .main-sidebar {
      left: inherit !important ;
    }
  }

  @supports not (-webkit-touch-callout: none) {
    .layout-fixed & .sidebar {
      height: calc(100vh - (#{$main-header-height-inner} + #{$main-header-bottom-border-width})) !important ;
    }
    .layout-fixed.text-sm & .sidebar {
      height: calc(100vh - (#{$main-header-height-sm-inner} + #{$main-header-bottom-border-width})) !important ;
    }
  }

  .layout-navbar-fixed.layout-fixed & {
    .control-sidebar {
      top: $main-header-height !important ;
    }

    .main-header.text-sm ~ .control-sidebar {
      top: $main-header-height-sm !important ;
    }

    .sidebar {
      margin-top: $main-header-height !important ;
    }

    .brand-link.text-sm ~ .sidebar {
      margin-top: $main-header-height-sm !important ;
    }
  }

  .layout-navbar-fixed.layout-fixed.text-sm & {
    .control-sidebar {
      top: $main-header-height-sm !important ;
    }

    .sidebar {
      margin-top: $main-header-height-sm !important ;
    }
  }

  .layout-navbar-fixed.sidebar-mini.sidebar-collapse &,
  .layout-navbar-fixed.sidebar-mini-md.sidebar-collapse &,
  .layout-navbar-fixed.sidebar-mini-xs.sidebar-collapse & {
    .brand-link {
      height: $main-header-height !important ;
      width: $sidebar-mini-width !important ;

      &.text-sm {
        height: $main-header-height-sm !important ;
      }
    }
  }

  .layout-navbar-fixed.sidebar-mini.sidebar-collapse.text-sm &,
  .layout-navbar-fixed.sidebar-mini-md.sidebar-collapse.text-sm &,
  .layout-navbar-fixed.sidebar-mini-xs.sidebar-collapse.text-sm & {
    .brand-link {
      height: $main-header-height-sm !important ;
    }
  }

  body:not(.layout-fixed).layout-navbar-fixed & {
    .main-sidebar {
      // margin-top: calc(#{$main-header-height} / -1) !important ;

      // .sidebar {
      //   margin-top: $main-header-height !important ;
      // }
    }
  }

  body:not(.layout-fixed).layout-navbar-fixed.text-sm & {
    .main-sidebar {
      margin-top: calc(#{$main-header-height-sm} / -1) !important ;

      .sidebar {
        margin-top: $main-header-height-sm !important ;
      }
    }
  }

  .layout-navbar-fixed & {
    .control-sidebar {
      top: 0 !important ;
    }

    a.anchor {
      display: block !important ;
      position: relative !important ;
      top: calc((#{$main-header-height-inner} + #{$main-header-bottom-border-width} + (#{$main-header-link-padding-y} * 2)) / -1) !important ;
    }

    .main-sidebar:hover {
      .brand-link {
        transition: width $transition-speed $transition-fn !important ;
        width: $sidebar-width !important ;
      }
    }

    .brand-link {
      overflow: hidden !important ;
      position: fixed !important ;
      top: 0 !important ;
      transition: width $transition-speed $transition-fn !important ;
      width: $sidebar-width !important ;
      z-index: $zindex-main-header + 1 !important ;
    }

    // Sidebar variants brand-link fix
    @each $name, $color in $theme-colors {
      .sidebar-dark-#{$name} .brand-link:not([class*="navbar"]) {
        background-color: $sidebar-dark-bg !important ;
      }

      .sidebar-light-#{$name} .brand-link:not([class*="navbar"]) {
        background-color: $sidebar-light-bg !important ;
      }
    }

    @each $name, $color in $colors {
      .sidebar-dark-#{$name} .brand-link:not([class*="navbar"]) {
        background-color: $sidebar-dark-bg !important ;
      }

      .sidebar-light-#{$name} .brand-link:not([class*="navbar"]) {
        background-color: $sidebar-light-bg !important ;
      }
    }

    .main-header.border-bottom-0 ~ .content-wrapper {
      margin-top: $main-header-height-inner !important ;
    }
    .content-wrapper {
      margin-top: $main-header-height !important ;
    }

    .main-header.text-sm ~ .content-wrapper {
      margin-top: $main-header-height-sm !important ;
    }

    .main-header {
      left: 0 !important ;
      position: fixed !important ;
      right: 0 !important ;
      top: 0 !important ;
      z-index: $zindex-main-header - 1 !important ;
    }
  }

  .layout-navbar-fixed.text-sm & {
    .content-wrapper {
      margin-top: $main-header-height-sm !important ;
    }
  }

  .layout-navbar-not-fixed & {
    .brand-link {
      position: static !important ;
    }

    .sidebar,
    .content-wrapper {
      margin-top: 0 !important ;
    }

    .main-header {
      position: static !important ;
    }
  }

  .layout-navbar-not-fixed.layout-fixed & {
    .sidebar {
      margin-top: 0 !important ;
    }
  }

  @each $breakpoint in map-keys($grid-breakpoints) {
    @include media-breakpoint-up($breakpoint) {
      $infix: breakpoint-infix($breakpoint, $grid-breakpoints) !important ;

      .layout#{$infix}-navbar-fixed.layout-fixed & {
        .control-sidebar {
          top: $main-header-height !important ;
        }

        .text-sm & .main-header ~ .control-sidebar,
        .main-header.text-sm ~ .control-sidebar {
          top: $main-header-height-sm !important ;
        }

        .sidebar {
          margin-top: $main-header-height !important ;
        }

        .text-sm & .brand-link ~ .sidebar,
        .brand-link.text-sm ~ .sidebar {
          margin-top: $main-header-height-sm !important ;
        }
      }

      .layout#{$infix}-navbar-fixed.layout-fixed.text-sm & {
        .control-sidebar {
          top: $main-header-height-sm !important ;
        }

        .sidebar {
          margin-top: $main-header-height-sm !important ;
        }
      }

      .layout#{$infix}-navbar-fixed & {
        .control-sidebar {
          top: 0 !important ;
        }

        a.anchor {
          display: block !important ;
          position: relative !important ;
          top: calc((#{$main-header-height-inner} + #{$main-header-bottom-border-width} + (#{$main-header-link-padding-y} * 2)) / -1) !important ;
        }

        &.sidebar-collapse {
          .brand-link {
            height: $main-header-height !important ;
            transition: width $transition-speed $transition-fn !important ;
            width: $sidebar-mini-width !important ;

            .text-sm &,
            &.text-sm {
              height: $main-header-height-sm !important ;
            }
          }

          .main-sidebar:hover {
            .brand-link {
              transition: width $transition-speed $transition-fn !important ;
              width: $sidebar-width !important ;
            }
          }
        }

        .brand-link {
          overflow: hidden !important ;
          position: fixed !important ;
          top: 0 !important ;
          transition: width $transition-speed $transition-fn !important ;
          width: $sidebar-width !important ;
          z-index: $zindex-main-header + 1 !important ;
        }

        .content-wrapper {
          margin-top: $main-header-height !important ;
        }

        .text-sm & .main-header ~ .content-wrapper,
        .main-header.text-sm ~ .content-wrapper {
          margin-top: $main-header-height-sm !important ;
        }

        .main-header {
          left: 0 !important ;
          position: fixed !important ;
          right: 0 !important ;
          top: 0 !important ;
          z-index: $zindex-main-sidebar - 1 !important ;
        }
      }

      .layout#{$infix}-navbar-fixed.text-sm & {
        .content-wrapper {
          margin-top: $main-header-height-sm !important ;
        }
      }

      body:not(.layout-fixed).layout#{$infix}-navbar-fixed & {
        // .main-sidebar {
        //   margin-top: calc(#{$main-header-height} / -1) !important ;

        //   .sidebar {
        //     margin-top: $main-header-height !important ;
        //   }
        // }
      }

      body:not(.layout-fixed).layout#{$infix}-navbar-fixed.text-sm & {
        .main-sidebar {
          margin-top: calc(#{$main-header-height-sm} / -1) !important ;

          .sidebar {
            margin-top: $main-header-height-sm !important ;
          }
        }
      }

      .layout#{$infix}-navbar-not-fixed & {
        .brand-link {
          position: static !important ;
        }

        .sidebar,
        .content-wrapper {
          margin-top: 0 !important ;
        }

        .main-header {
          position: static !important ;
        }
      }

      .layout#{$infix}-navbar-not-fixed.layout-fixed & {
        .sidebar {
          margin-top: 0 !important ;
        }
      }
    }
  }

  .layout-footer-fixed & {
    .control-sidebar {
      bottom: 0 !important ;
    }

    .main-footer {
      bottom: 0 !important ;
      left: 0 !important ;
      position: fixed !important ;
      right: 0 !important ;
      z-index: $zindex-main-footer !important ;
    }
  }

  .layout-footer-not-fixed & {
    .main-footer {
      position: static !important ;
    }

    .content-wrapper {
      margin-bottom: 0 !important ;
    }
  }

  @each $breakpoint in map-keys($grid-breakpoints) {
    @include media-breakpoint-up($breakpoint) {
      $infix: breakpoint-infix($breakpoint, $grid-breakpoints) !important ;
      .layout#{$infix}-footer-fixed & {
        .control-sidebar {
          bottom: 0 !important ;
        }

        .main-footer {
          bottom: 0 !important ;
          left: 0 !important ;
          position: fixed !important ;
          right: 0 !important ;
          z-index: $zindex-main-footer !important ;
        }

        .content-wrapper {
          padding-bottom: $main-footer-height !important ;
        }
      }

      .layout#{$infix}-footer-not-fixed & {
        .main-footer {
          position: static !important ;
        }
      }
    }
  }

  .layout-top-nav & {
    margin-left: 0 !important ;

    .main-header {
      .brand-image {
        margin-top: -.5rem !important ;
        margin-right: .2rem !important ;
        height: 33px !important ;
      }
    }

    .main-sidebar {
      bottom: inherit !important ;
      height: inherit !important ;
    }

    .content-wrapper,
    .main-header,
    .main-footer {
      margin-left: 0 !important ;
    }
  }
}


body.sidebar-collapse:not(.sidebar-mini-xs):not(.sidebar-mini-md):not(.sidebar-mini) {
  .content-wrapper,
  .main-footer,
  .main-header {
    &,
    &::before {
      margin-left: 0 !important ;
    }
  }
}

body:not(.sidebar-mini-md):not(.sidebar-mini-xs):not(.layout-top-nav) {
  .content-wrapper,
  .main-footer,
  .main-header {
    @include media-breakpoint-up(md) {
      @include transition(margin-left $transition-speed $transition-fn) !important ;

      margin-left: $sidebar-width !important ;

      .sidebar-collapse & {
        margin-left: 0 !important ;
      }
    }

    @include media-breakpoint-down(md) {
      margin-left: 0 !important ;
    }
  }
}

.sidebar-mini-md {
  .content-wrapper,
  .main-footer,
  .main-header {
    @include media-breakpoint-up(md) {
      @include transition(margin-left $transition-speed $transition-fn) !important ;

      margin-left: $sidebar-width !important ;

      .sidebar-collapse & {
        margin-left: $sidebar-mini-width !important ;
      }
    }
    @include media-breakpoint-down(md) {
      margin-left: $sidebar-mini-width !important ;
    }
    @include media-breakpoint-down(sm) {
      margin-left: 0 !important ;
    }
  }
}

.sidebar-mini-xs {
  .content-wrapper,
  .main-footer,
  .main-header {
    @include media-breakpoint-up(md) {
      @include transition(margin-left $transition-speed $transition-fn) !important ;

      margin-left: $sidebar-width !important ;

      .sidebar-collapse & {
        margin-left: $sidebar-mini-width !important ;
      }
    }
    @include media-breakpoint-down(md) {
      margin-left: $sidebar-mini-width !important ;
    }
  }
}

.content-wrapper {
  background-color: $main-bg !important ;

  > .content {
    padding: $content-padding-y $content-padding-x !important ;
  }
}

.main-sidebar {
  &,
  &::before {
    $local-sidebar-transition: margin-left $transition-speed $transition-fn, width $transition-speed $transition-fn !important ;
    @include transition($local-sidebar-transition) !important ;
    width: $sidebar-width !important ;
  }

  .sidebar-collapse:not(.sidebar-mini):not(.sidebar-mini-md):not(.sidebar-mini-xs) & {
    &,
    &::before {
      box-shadow: none !important !important ;
    }
  }

  .sidebar-collapse & {
    &,
    &::before {
      margin-left: -$sidebar-width !important ;
    }

    .nav-sidebar.nav-child-indent .nav-treeview {
      padding: 0 !important ;
    }
  }

  @include media-breakpoint-down(sm) {
    &,
    &::before {
      box-shadow: none !important !important ;
      margin-left: -$sidebar-width !important ;
    }

    .sidebar-open & {
      &,
      &::before {
        margin-left: 0 !important ;
      }
    }
  }
}

body:not(.layout-fixed) {
  .main-sidebar {
    height: inherit !important ;
    min-height: 100% !important ;
    position: absolute !important ;
    top: 0 !important ;

    .sidebar {
      overflow-y: auto !important ;
    }
  }
}

.layout-fixed {
  .brand-link {
    width: $sidebar-width !important ;
  }

  .main-sidebar {
    bottom: 0 !important ;
    float: none !important ;
    left: 0 !important ;
    position: fixed !important ;
    top: 0 !important ;
  }

  .control-sidebar {
    bottom: 0 !important ;
    float: none !important ;
    position: fixed !important ;
    top: 0 !important ;

    .control-sidebar-content {
      height: calc(100vh - #{$main-header-height}) !important ;
      overflow-y: auto !important ;
      @include scrollbar-width-thin() !important ;
      @include scrollbar-color-gray() !important ;
    }
  }
}

@supports (-webkit-touch-callout: none) {
  .layout-fixed {
    .main-sidebar {
      height: inherit !important ;
    }
  }
}

.main-footer {
  background-color: $main-footer-bg !important ;
  border-top: $main-footer-border-top !important ;
  color: lighten($gray-700, 25%) !important ;
  padding: $main-footer-padding !important ;

  .text-sm &,
  &.text-sm {
    padding: $main-footer-padding-sm !important ;
  }
}

.content-header {
  padding: 15px $content-padding-x !important ;

  .text-sm & {
    padding: 10px $content-padding-x !important ;
  }

  h1 {
    font-size: 1.8rem !important ;
    margin: 0 !important ;

    .text-sm & {
      font-size: 1.5rem !important ;
    }
  }

  .breadcrumb {
    background-color: transparent !important ;
    line-height: 1.8rem !important ;
    margin-bottom: 0 !important ;
    padding: 0 !important ;

    .text-sm & {
      line-height: 1.5rem !important ;
    }
  }
}


.hold-transition {
  .content-wrapper,
  .main-header,
  .main-sidebar,
  .main-sidebar *,
  .control-sidebar,
  .control-sidebar *,
  .main-footer {
    transition: none !important !important ;
    animation-duration: 0s !important !important ;
  }
}

@include dark-mode () {
  background-color: $dark-main-bg !important ;
  color: $white !important ;

  .wrapper {
    .layout-navbar-fixed & {
      @each $name, $color in $theme-colors-alt {
        .sidebar-dark-#{$name} .brand-link:not([class*="navbar"]) {
          background-color: $sidebar-dark-bg !important ;
        }

        .sidebar-light-#{$name} .brand-link:not([class*="navbar"]) {
          background-color: $sidebar-light-bg !important ;
        }
      }
    }

    @each $breakpoint in map-keys($grid-breakpoints) {
      @include media-breakpoint-up($breakpoint) {
        $infix: breakpoint-infix($breakpoint, $grid-breakpoints) !important ;

        .layout#{$infix}-navbar-fixed & {
          @each $name, $color in $theme-colors-alt {
            .sidebar-dark-#{$name} .brand-link:not([class*="navbar"]) {
              background-color: $sidebar-dark-bg !important ;
            }

            .sidebar-light-#{$name} .brand-link:not([class*="navbar"]) {
              background-color: $sidebar-light-bg !important ;
            }
          }
        }
      }
    }
  }

  .breadcrumb-item {
    &.active,
    + .breadcrumb-item::before {
      color: $gray-500 !important ;
    }
  }
  .main-footer {
    background-color: $dark !important ;
    border-color: lighten($dark, 10%) !important ;
  }
  .content-wrapper {
    background-color: lighten($dark, 7.5%) !important ;
    color: $white !important ;

    .content-header {
      color: $white !important ;
    }
  }
}
