//
// Plugin: Pace
//

.pace {
  z-index: $zindex-main-sidebar + 10 !important ;

  .pace-progress {
    z-index: $zindex-main-sidebar + 11 !important ;
  }

  .pace-activity {
    z-index: $zindex-main-sidebar + 12 !important ;
  }
}

// Mixin
@mixin pace-variant($name, $color) {
  .pace-#{$name} {
    .pace {
      .pace-progress {
        background: $color !important ;
      }
    }
  }

  .pace-barber-shop-#{$name} {
    .pace {
      background: color-yiq($color) !important ;

      .pace-progress {
        background: $color !important ;
      }

      .pace-activity {
        background-image: linear-gradient(45deg, rgba(color-yiq($color), 0.2) 25%, transparent 25%, transparent 50%, rgba(color-yiq($color), 0.2) 50%, rgba(color-yiq($color), 0.2) 75%, transparent 75%, transparent) !important ;
      }
    }
  }

  .pace-big-counter-#{$name} {
    .pace {
      .pace-progress::after {
        color: rgba($color, .19999999999999996) !important ;
      }
    }
  }

  .pace-bounce-#{$name} {
    .pace {
      .pace-activity {
        background: $color !important ;
      }
    }
  }

  .pace-center-atom-#{$name} {
    .pace-progress {
      height: 100px !important ;
      width: 80px !important ;

      &::before {
        background: $color !important ;
        color: color-yiq($color) !important ;
        font-size: .8rem !important ;
        line-height: .7rem !important ;
        padding-top: 17% !important ;
      }
    }

    .pace-activity {
      border-color: $color !important ;

      &::after,
      &::before {
        border-color: $color !important ;
      }
    }
  }

  .pace-center-circle-#{$name} {
    .pace {
      .pace-progress {
        background: rgba($color, .8) !important ;
        color: color-yiq($color) !important ;
      }
    }
  }

  .pace-center-radar-#{$name} {
    .pace {
      .pace-activity {
        border-color: $color transparent transparent !important ;
      }

      .pace-activity::before {
        border-color: $color transparent transparent !important ;
      }
    }
  }

  .pace-center-simple-#{$name} {
    .pace {
      background: color-yiq($color) !important ;
      border-color: $color !important ;

      .pace-progress {
        background: $color !important ;
      }
    }
  }

  .pace-material-#{$name} {
    .pace {
      color: $color !important ;
    }
  }

  .pace-corner-indicator-#{$name} {
    .pace {
      .pace-activity {
        background: $color !important ;
      }

      .pace-activity::after,
      .pace-activity::before {
        border: 5px solid color-yiq($color) !important ;
      }


      .pace-activity::before {
          border-right-color: rgba($color, .2) !important ;
          border-left-color: rgba($color, .2) !important ;
      }

      .pace-activity::after {
          border-top-color: rgba($color, .2) !important ;
          border-bottom-color: rgba($color, .2) !important ;
      }
    }
  }

  .pace-fill-left-#{$name} {
    .pace {
      .pace-progress {
        background-color: rgba($color, 0.19999999999999996) !important ;
      }
    }
  }

  .pace-flash-#{$name} {
    .pace {
      .pace-progress {
        background: $color !important ;
      }

      .pace-progress-inner {
        box-shadow: 0 0 10px $color, 0 0 5px $color !important ;
      }

      .pace-activity {
        border-top-color: $color !important ;
        border-left-color: $color !important ;
      }
    }
  }

  .pace-loading-bar-#{$name} {
    .pace {
      .pace-progress {
        background: $color !important ;
        color: $color !important ;
        box-shadow: 120px 0 color-yiq($color), 240px 0 color-yiq($color) !important ;
      }

      .pace-activity {
        box-shadow: inset 0 0 0 2px $color, inset 0 0 0 7px color-yiq($color) !important ;
      }
    }
  }

  .pace-mac-osx-#{$name} {
    .pace {
      .pace-progress {
        background-color: $color !important ;
        box-shadow: inset -1px 0 $color, inset 0 -1px $color, inset 0 2px rgba(color-yiq($color), 0.5), inset 0 6px rgba(color-yiq($color), .3) !important ;
      }

      .pace-activity {
        background-image: radial-gradient(rgba(color-yiq($color), .65) 0%, rgba(color-yiq($color), .15) 100%) !important ;
        height: 12px !important ;
      }
    }
  }

  .pace-progress-color-#{$name} {
    .pace-progress {
      color: $color !important ;
    }
  }
}


@each $name, $color in $theme-colors {
  @include pace-variant($name, $color) !important ;
}

@each $name, $color in $colors {
  @include pace-variant($name, $color) !important ;
}

