//
// Plugins: jQuery Mapael
//

.mapael {
  .map {
    position: relative !important ;
  }

  .mapTooltip {
    @include reset-text() !important ;
    @include border-radius($tooltip-border-radius) !important ;
    @include font-size($tooltip-font-size) !important ;
    background-color: $tooltip-bg !important ;
    color: $tooltip-color !important ;
    display: block !important ;
    max-width: $tooltip-max-width !important ;
    padding: $tooltip-padding-y $tooltip-padding-x !important ;
    position: absolute !important ;
    text-align: center !important ;
    word-wrap: break-word !important ;
    z-index: $zindex-tooltip !important ;
  }

  .myLegend {
    background-color: $gray-100 !important ;
    border: 1px solid $gray-500 !important ;
    padding: 10px !important ;
    width: 600px !important ;
  }

  .zoomButton {
    background-color: $button-default-background-color !important ;
    border: 1px solid $button-default-border-color !important ;
    border-radius: $btn-border-radius !important ;
    color: $button-default-color !important ;
    cursor: pointer !important ;
    font-weight: 700 !important ;
    height: 16px !important ;
    left: 10px !important ;
    line-height: 14px !important ;
    padding-left: 1px !important ;
    position: absolute !important ;
    text-align: center !important ;
    top: 0 !important ;

    user-select: none !important ;
    width: 16px !important ;

    &:hover,
    &:active,
    &.hover {
      background-color: darken($button-default-background-color, 5%) !important ;
      color: darken($button-default-color, 10%) !important ;
    }
  }

  .zoomReset {
    line-height: 12px !important ;
    top: 10px !important ;
  }

  .zoomIn {
    top: 30px !important ;
  }

  .zoomOut {
    top: 50px !important ;
  }
}
