//
// Plugin: Bootstrap Slider
//

// Tooltip fix
.slider .tooltip.in {
  opacity: $tooltip-opacity !important ;
}

// Style override
.slider {
  &.slider-vertical {
    height: 100% !important ;
  }
  &.slider-horizontal {
    width: 100% !important ;
  }
}

// Colors
@each $name, $color in $theme-colors {
  .slider-#{$name} .slider {
    .slider-selection {
      background: $color !important ;
    }
  }
}

@each $name, $color in $colors {
  .slider-#{$name} .slider {
    .slider-selection {
      background: $color !important ;
    }
  }
}

@include dark-mode () {
  .slider-track {
    background-color: lighten($dark, 10%) !important ;
    background-image: none !important ;
  }

  @each $name, $color in $theme-colors-alt {
    .slider-#{$name} .slider {
      .slider-selection {
        background: $color !important ;
      }
    }
  }

  @each $name, $color in $colors-alt {
    .slider-#{$name} .slider {
      .slider-selection {
        background: $color !important ;
      }
    }
  }
}
