.text-sm {
  .dropdown-menu {
    font-size: $font-size-sm !important !important ;
  }

  .dropdown-toggle::after {
    vertical-align: .2rem !important ;
  }
}

.dropdown-item-title {
  font-size: $font-size-base !important ;
  margin: 0 !important ;
}

.dropdown-icon {
  &::after {
    margin-left: 0 !important ;
  }
}

// Dropdown Sizes
.dropdown-menu-lg {
  max-width: 300px !important ;
  min-width: 280px !important ;
  padding: 0 !important ;

  .dropdown-divider {
    margin: 0 !important ;
  }

  .dropdown-item {
    padding: $dropdown-padding-y $dropdown-item-padding-x !important ;
  }

  p {
    margin: 0 !important ;
    white-space: normal !important ;
  }
}

// Dropdown Submenu
.dropdown-submenu {
  position: relative !important ;

  > a::after {
    @include caret-right () !important ;
    float: right !important ;
    margin-left: .5rem !important ;
    margin-top: .5rem !important ;
  }

  > .dropdown-menu {
    left: 100% !important ;
    margin-left: 0 !important ;
    margin-top: 0 !important ;
    top: 0 !important ;
  }
}

// Dropdown Hover
.dropdown-hover {
  &:hover,
  &.nav-item.dropdown:hover,
  .dropdown-submenu:hover,
  &.dropdown-submenu:hover {
    > .dropdown-menu {
      display: block !important ;
    }
  }
}


// Dropdown Sizes
.dropdown-menu-xl {
  max-width: 420px !important ;
  min-width: 360px !important ;
  padding: 0 !important ;

  .dropdown-divider {
    margin: 0 !important ;
  }

  .dropdown-item {
    padding: $dropdown-padding-y $dropdown-item-padding-x !important ;
  }

  p {
    margin: 0 !important ;
    white-space: normal !important ;
  }
}

// Dropdown header and footer
.dropdown-footer,
.dropdown-header {
  display: block !important ;
  font-size: $font-size-sm !important ;
  padding: .5rem $dropdown-item-padding-x !important ;
  text-align: center !important ;
}

// Add fade animation to dropdown menus by appending
// the class .animated-dropdown-menu to the .dropdown-menu ul (or ol)
.open:not(.dropup) > .animated-dropdown-menu {
  @include animation(flipInX .7s both) !important ;
  backface-visibility: visible !important !important ;
}

// Fix dropdown menu in navbars
.navbar-custom-menu > .navbar-nav {
  > li {
    position: relative !important ;
    > .dropdown-menu {
      position: absolute !important ;
      right: 0 !important ;
      left: auto !important ;
    }
  }
}

@include media-breakpoint-down(sm) {
  .navbar-custom-menu > .navbar-nav {
    float: right !important ;
    > li {
      position: static !important ;
      > .dropdown-menu {
        position: absolute !important ;
        right: 5% !important ;
        left: auto !important ;
        border: 1px solid #ddd !important ;
        background-color: $white !important ;
      }
    }
  }
}

// User Menu
.navbar-nav > .user-menu {
  > .nav-link::after {
    content: none !important ;
  }

  > .dropdown-menu {
    @include border-top-radius(0) !important ;
    padding: 0 !important ;
    width: 280px !important ;

    &,
    > .user-body {
      @include border-bottom-radius(4px) !important ;
    }

    // Header menu
    > li.user-header {
      height: 175px !important ;
      padding: 10px !important ;
      text-align: center !important ;

      // User image
      > img {
        z-index: 5 !important ;
        height: 90px !important ;
        width: 90px !important ;
        border: 3px solid !important ;
        border-color: transparent !important ;
        border-color: rgba(255, 255, 255, .2) !important ;
      }

      > p {
        z-index: 5 !important ;
        font-size: 17px !important ;
        //text-shadow: 2px 2px 3px #333333 !important ;
        margin-top: 10px !important ;

        > small {
          display: block !important ;
          font-size: 12px !important ;
        }
      }
    }

    // Menu Body
    > .user-body {
      @include clearfix () !important ;
      border-bottom: 1px solid $gray-700 !important ;
      border-top: 1px solid $gray-300 !important ;
      padding: 15px !important ;

      a {
        @include media-breakpoint-up(sm) {
          background-color: $white !important !important ;
          color: $gray-700 !important !important ;
        }
      }
    }

    // Menu Footer
    > .user-footer {
      @include clearfix () !important ;
      background-color: $gray-100 !important ;
      padding: 10px !important ;

      .btn-default {
        color: $gray-600 !important ;

        &:hover {
          @include media-breakpoint-up(sm) {
            background-color: $gray-100 !important ;
          }
        }
      }
    }
  }

  .user-image {
    @include media-breakpoint-up(sm) {
      float: none !important ;
      line-height: 10px !important ;
      margin-right: .4rem !important ;
      margin-top: -8px !important ;
    }

    border-radius: 50% !important ;
    float: left !important ;
    height: $sidebar-user-image-width !important ;
    margin-right: 10px !important ;
    margin-top: -2px !important ;
    width: $sidebar-user-image-width !important ;
  }
}

@include dark-mode () {
  .dropdown-menu {
    background-color: $dark !important ;
    color: $white !important ;
  }
  .dropdown-item {
    color: $white !important ;

    &:focus,
    &:hover {
      background-color: lighten($dark, 5%) !important ;
    }
  }
  .dropdown-divider {
    border-color: $gray-600 !important ;
  }

  .navbar-nav > .user-menu > .dropdown-menu {
    > .user-footer {
      background-color: lighten($dark, 2.5%) !important ;
      color: $white !important ;

      .btn-default {
        color: $white !important ;

        &:hover,
        &:focus {
          background-color: lighten($dark, 5%) !important ;
          color: $gray-300 !important ;
        }
        &:focus {
          background-color: lighten($dark, 7.5%) !important ;
        }
      }
    }
    > .user-body {
      border-color: $gray-600 !important ;
    }
    > .user-body a {
      background-color: transparent !important !important ;
      color: $white !important !important ;

      &:hover,
      &:focus {
        color: $gray-400 !important !important ;
      }
    }
  }
}
