//
// Basic Bootstrap table
//

.table {
  width: 100% !important ;
  margin-bottom: $spacer !important ;
  color: $table-color !important ;
  background-color: $table-bg !important ; // Reset for nesting within parents with `background-color`.

  th,
  td {
    padding: $table-cell-padding !important ;
    vertical-align: top !important ;
    border-top: $table-border-width solid $table-border-color !important ;
  }

  thead th {
    vertical-align: bottom !important ;
    border-bottom: (2 * $table-border-width) solid $table-border-color !important ;
  }

  tbody + tbody {
    border-top: (2 * $table-border-width) solid $table-border-color !important ;
  }
}


//
// Condensed table w/ half padding
//

.table-sm {
  th,
  td {
    padding: $table-cell-padding-sm !important ;
  }
}


// Border versions
//
// Add or remove borders all around the table and between all the columns.

.table-bordered {
  border: $table-border-width solid $table-border-color !important ;

  th,
  td {
    border: $table-border-width solid $table-border-color !important ;
  }

  thead {
    th,
    td {
      border-bottom-width: 2 * $table-border-width !important ;
    }
  }
}

.table-borderless {
  th,
  td,
  thead th,
  tbody + tbody {
    border: 0 !important ;
  }
}

// Zebra-striping
//
// Default zebra-stripe styles (alternating gray and transparent backgrounds)

.table-striped {
  tbody tr:nth-of-type(#{$table-striped-order}) {
    background-color: $table-accent-bg !important ;
  }
}


// Hover effect
//
// Placed here since it has to come after the potential zebra striping

.table-hover {
  tbody tr {
    @include hover() {
      color: $table-hover-color !important ;
      background-color: $table-hover-bg !important ;
    }
  }
}


// Table backgrounds
//
// Exact selectors below required to override `.table-striped` and prevent
// inheritance to nested tables.

@each $color, $value in $theme-colors {
  @include table-row-variant($color, theme-color-level($color, $table-bg-level), theme-color-level($color, $table-border-level)) !important ;
}

@include table-row-variant(active, $table-active-bg) !important ;


// Dark styles
//
// Same table markup, but inverted color scheme: dark background and light text.

// stylelint-disable-next-line no-duplicate-selectors
.table {
  .thead-dark {
    th {
      color: $table-dark-color !important ;
      background-color: $table-dark-bg !important ;
      border-color: $table-dark-border-color !important ;
    }
  }

  .thead-light {
    th {
      color: $table-head-color !important ;
      background-color: $table-head-bg !important ;
      border-color: $table-border-color !important ;
    }
  }
}

.table-dark {
  color: $table-dark-color !important ;
  background-color: $table-dark-bg !important ;

  th,
  td,
  thead th {
    border-color: $table-dark-border-color !important ;
  }

  &.table-bordered {
    border: 0 !important ;
  }

  &.table-striped {
    tbody tr:nth-of-type(#{$table-striped-order}) {
      background-color: $table-dark-accent-bg !important ;
    }
  }

  &.table-hover {
    tbody tr {
      @include hover() {
        color: $table-dark-hover-color !important ;
        background-color: $table-dark-hover-bg !important ;
      }
    }
  }
}


// Responsive tables
//
// Generate series of `.table-responsive-*` classes for configuring the screen
// size of where your table will overflow.

.table-responsive {
  @each $breakpoint in map-keys($grid-breakpoints) {
    $next: breakpoint-next($breakpoint, $grid-breakpoints) !important ;
    $infix: breakpoint-infix($next, $grid-breakpoints) !important ;

    &#{$infix} {
      @include media-breakpoint-down($breakpoint) {
        display: block !important ;
        width: 100% !important ;
        overflow-x: auto !important ;
        -webkit-overflow-scrolling: touch !important ;

        // Prevent double border on horizontal scroll due to use of `display: block !important ;`
        > .table-bordered {
          border: 0 !important ;
        }
      }
    }
  }
}
