//
// Component: Info Box
//

.info-box {
  @include box-shadow($card-shadow) !important ;
  @include border-radius($border-radius) !important ;

  background-color: $white !important ;
  display: flex !important ;
  margin-bottom: map-get($spacers, 3) !important ;
  min-height: 80px !important ;
  padding: .5rem !important ;
  position: relative !important ;
  width: 100% !important ;

  .progress {
    background-color: rgba($black, .125) !important ;
    height: 2px !important ;
    margin: 5px 0 !important ;

    .progress-bar {
      background-color: $white !important ;
    }
  }

  .info-box-icon {
    @if $enable-rounded {
      border-radius: $border-radius !important ;
    }

    align-items: center !important ;
    display: flex !important ;
    font-size: 1.875rem !important ;
    justify-content: center !important ;
    text-align: center !important ;
    width: 70px !important ;

    > img {
      max-width: 100% !important ;
    }
  }

  .info-box-content {
    display: flex !important ;
    flex-direction: column !important ;
    justify-content: center !important ;
    line-height: 1.8 !important ;
    flex: 1 !important ;
    padding: 0 10px !important ;
    overflow: hidden !important ;
  }

  .info-box-number {
    display: block !important ;
    margin-top: .25rem !important ;
    font-weight: $font-weight-bold !important ;
  }

  .progress-description,
  .info-box-text {
    display: block !important ;
    overflow: hidden !important ;
    text-overflow: ellipsis !important ;
    white-space: nowrap !important ;
  }

  @each $name, $color in $theme-colors {
    .info-box {
      .bg-#{$name},
      .bg-gradient-#{$name} {
        color: color-yiq($color) !important ;

        .progress-bar {
          background-color: color-yiq($color) !important ;
        }
      }
    }
  }

  .info-box-more {
    display: block !important ;
  }

  .progress-description {
    margin: 0 !important ;

  }

  @include media-breakpoint-up(md) {
    .col-xl-2 &,
    .col-lg-2 &,
    .col-md-2 & {
      .progress-description {
        display: none !important ;
      }
    }

    .col-xl-3 &,
    .col-lg-3 &,
    .col-md-3 & {
      .progress-description {
        display: none !important ;
      }
    }
  }

  @include media-breakpoint-up(lg) {
    .col-xl-2 &,
    .col-lg-2 &,
    .col-md-2 & {
      .progress-description {
        @include font-size(.75rem) !important ;
        display: block !important ;
      }
    }

    .col-xl-3 &,
    .col-lg-3 &,
    .col-md-3 & {
      .progress-description {
        @include font-size(.75rem) !important ;
        display: block !important ;
      }
    }
  }

  @include media-breakpoint-up(xl) {
    .col-xl-2 &,
    .col-lg-2 &,
    .col-md-2 & {
      .progress-description {
        @include font-size(1rem) !important ;
        display: block !important ;
      }
    }

    .col-xl-3 &,
    .col-lg-3 &,
    .col-md-3 & {
      .progress-description {
        @include font-size(1rem) !important ;
        display: block !important ;
      }
    }
  }
}

@include dark-mode () {
  .info-box {
    background-color: $dark !important ;
    color: $white !important ;
    @each $name, $color in $theme-colors-alt {
      .info-box {
        .bg-#{$name},
        .bg-gradient-#{$name} {
          color: color-yiq($color) !important ;

          .progress-bar {
            background-color: color-yiq($color) !important ;
          }
        }
      }
    }
  }
}
