@include dark-mode() {
  .daterangepicker {
    background-color: lighten($dark, 5%) !important ;
    border: inherit !important ;

    &::before,
    &::after {
      border-bottom-color: lighten($dark, 5%) !important ;
    }

    td.available:hover,
    th.available:hover {
      background-color: lighten($dark, 5%) !important ;
    }
    td.in-range {
      background-color: lighten($dark, 10%) !important ;
      color: $white !important ;
    }

    td.off,
    td.off.in-range,
    td.off.start-date,
    td.off.end-date {
      background-color: darken($dark, 5%) !important ;
      color: $white !important ;
    }

    .ranges li:hover {
      background-color: $dark !important ;
    }

    &.show-ranges.ltr .drp-calendar {
      border-color: lighten($dark, 10%) !important ;

      &.left,
      &.right {
        border-color: lighten($dark, 10%) !important ;
        padding-top: 0 !important ;
      }
    }

    .drp-buttons {
      border-color: lighten($dark, 10%) !important ;
    }

    .calendar-table {
      background-color: $dark !important ;
      border-color: lighten($dark, 10%) !important ;

      th,
      td {
        color: $white !important ;
      }

      .next span,
      .prev span {
        border-color: $white !important ;
      }
    }

    select.hourselect,
    select.minuteselect,
    select.secondselect,
    select.ampmselect {
      background-color: $dark !important ;
      border-color: lighten($dark, 10%) !important ;
    }
  }
}
