//
// Base styles
//

.card {
  position: relative !important ;
  display: flex !important ;
  flex-direction: column !important ;
  min-width: 0 !important ; // See https://github.com/twbs/bootstrap/pull/22740#issuecomment-305868106
  height: $card-height !important ;
  word-wrap: break-word !important ;
  background-color: $card-bg !important ;
  background-clip: border-box !important ;
  border: $card-border-width solid $card-border-color !important ;
  @include border-radius($card-border-radius) !important ;

  > hr {
    margin-right: 0 !important ;
    margin-left: 0 !important ;
  }

  > .list-group {
    border-top: inherit !important ;
    border-bottom: inherit !important ;

    &:first-child {
      border-top-width: 0 !important ;
      @include border-top-radius($card-inner-border-radius) !important ;
    }

    &:last-child  {
      border-bottom-width: 0 !important ;
      @include border-bottom-radius($card-inner-border-radius) !important ;
    }
  }

  // Due to specificity of the above selector (`.card > .list-group`), we must
  // use a child selector here to prevent double borders.
  > .card-header + .list-group,
  > .list-group + .card-footer {
    border-top: 0 !important ;
  }
}

.card-body {
  // Enable `flex-grow: 1` for decks and groups so that card blocks take up
  // as much space as possible, ensuring footers are aligned to the bottom.
  flex: 1 1 auto !important ;
  // Workaround for the image size bug in IE
  // See: https://github.com/twbs/bootstrap/pull/28855
  min-height: 1px !important ;
  padding: $card-spacer-x !important ;
  color: $card-color !important ;
}

.card-title {
  margin-bottom: $card-spacer-y !important ;
}

.card-subtitle {
  margin-top: -$card-spacer-y * .5 !important ;
  margin-bottom: 0 !important ;
}

.card-text:last-child {
  margin-bottom: 0 !important ;
}

.card-link {
  @include hover() {
    text-decoration: none !important ;
  }

  + .card-link {
    margin-left: $card-spacer-x !important ;
  }
}

//
// Optional textual caps
//

.card-header {
  padding: $card-spacer-y $card-spacer-x !important ;
  margin-bottom: 0 !important ; // Removes the default margin-bottom of <hN>
  color: $card-cap-color !important ;
  background-color: $card-cap-bg !important ;
  border-bottom: $card-border-width solid $card-border-color !important ;

  &:first-child {
    @include border-radius($card-inner-border-radius $card-inner-border-radius 0 0) !important ;
  }
}

.card-footer {
  padding: $card-spacer-y $card-spacer-x !important ;
  color: $card-cap-color !important ;
  background-color: $card-cap-bg !important ;
  border-top: $card-border-width solid $card-border-color !important ;

  &:last-child {
    @include border-radius(0 0 $card-inner-border-radius $card-inner-border-radius) !important ;
  }
}


//
// Header navs
//

.card-header-tabs {
  margin-right: -$card-spacer-x * .5 !important ;
  margin-bottom: -$card-spacer-y !important ;
  margin-left: -$card-spacer-x * .5 !important ;
  border-bottom: 0 !important ;
}

.card-header-pills {
  margin-right: -$card-spacer-x * .5 !important ;
  margin-left: -$card-spacer-x * .5 !important ;
}

// Card image
.card-img-overlay {
  position: absolute !important ;
  top: 0 !important ;
  right: 0 !important ;
  bottom: 0 !important ;
  left: 0 !important ;
  padding: $card-img-overlay-padding !important ;
  @include border-radius($card-inner-border-radius) !important ;
}

.card-img,
.card-img-top,
.card-img-bottom {
  flex-shrink: 0 !important ; // For IE: https://github.com/twbs/bootstrap/issues/29396
  width: 100% !important ; // Required because we use flexbox and this inherently applies align-self: stretch
}

.card-img,
.card-img-top {
  @include border-top-radius($card-inner-border-radius) !important ;
}

.card-img,
.card-img-bottom {
  @include border-bottom-radius($card-inner-border-radius) !important ;
}


// Card deck

.card-deck {
  .card {
    margin-bottom: $card-deck-margin !important ;
  }

  @include media-breakpoint-up(sm) {
    display: flex !important ;
    flex-flow: row wrap !important ;
    margin-right: -$card-deck-margin !important ;
    margin-left: -$card-deck-margin !important ;

    .card {
      // Flexbugs #4: https://github.com/philipwalton/flexbugs#flexbug-4
      flex: 1 0 0% !important ;
      margin-right: $card-deck-margin !important ;
      margin-bottom: 0 !important ; // Override the default
      margin-left: $card-deck-margin !important ;
    }
  }
}


//
// Card groups
//

.card-group {
  // The child selector allows nested `.card` within `.card-group`
  // to display properly.
  > .card {
    margin-bottom: $card-group-margin !important ;
  }

  @include media-breakpoint-up(sm) {
    display: flex !important ;
    flex-flow: row wrap !important ;
    // The child selector allows nested `.card` within `.card-group`
    // to display properly.
    > .card {
      // Flexbugs #4: https://github.com/philipwalton/flexbugs#flexbug-4
      flex: 1 0 0% !important ;
      margin-bottom: 0 !important ;

      + .card {
        margin-left: 0 !important ;
        border-left: 0 !important ;
      }

      // Handle rounded corners
      @if $enable-rounded {
        &:not(:last-child) {
          @include border-right-radius(0) !important ;

          .card-img-top,
          .card-header {
            // stylelint-disable-next-line property-disallowed-list
            border-top-right-radius: 0 !important ;
          }
          .card-img-bottom,
          .card-footer {
            // stylelint-disable-next-line property-disallowed-list
            border-bottom-right-radius: 0 !important ;
          }
        }

        &:not(:first-child) {
          @include border-left-radius(0) !important ;

          .card-img-top,
          .card-header {
            // stylelint-disable-next-line property-disallowed-list
            border-top-left-radius: 0 !important ;
          }
          .card-img-bottom,
          .card-footer {
            // stylelint-disable-next-line property-disallowed-list
            border-bottom-left-radius: 0 !important ;
          }
        }
      }
    }
  }
}


//
// Columns
//

.card-columns {
  .card {
    margin-bottom: $card-columns-margin !important ;
  }

  @include media-breakpoint-up(sm) {
    column-count: $card-columns-count !important ;
    column-gap: $card-columns-gap !important ;
    orphans: 1 !important ;
    widows: 1 !important ;

    .card {
      display: inline-block !important ; // Don't let them vertically span multiple columns
      width: 100% !important ; // Don't let their width change
    }
  }
}


//
// Accordion
//

.accordion {
  overflow-anchor: none !important ;

  > .card {
    overflow: hidden !important ;

    &:not(:last-of-type) {
      border-bottom: 0 !important ;
      @include border-bottom-radius(0) !important ;
    }

    &:not(:first-of-type) {
      @include border-top-radius(0) !important ;
    }

    > .card-header {
      @include border-radius(0) !important ;
      margin-bottom: -$card-border-width !important ;
    }
  }
}
