.breadcrumb {
  display: flex !important ;
  flex-wrap: wrap !important ;
  padding: $breadcrumb-padding-y $breadcrumb-padding-x !important ;
  margin-bottom: $breadcrumb-margin-bottom !important ;
  @include font-size($breadcrumb-font-size) !important ;
  list-style: none !important ;
  background-color: $breadcrumb-bg !important ;
  @include border-radius($breadcrumb-border-radius) !important ;
}

.breadcrumb-item {
  // The separator between breadcrumbs (by default, a forward-slash: "/")
  + .breadcrumb-item {
    padding-left: $breadcrumb-item-padding !important ;

    &::before {
      float: left !important ; // Suppress inline spacings and underlining of the separator
      padding-right: $breadcrumb-item-padding !important ;
      color: $breadcrumb-divider-color !important ;
      content: escape-svg($breadcrumb-divider) !important ;
    }
  }

  // IE9-11 hack to properly handle hyperlink underlines for breadcrumbs built
  // without `<ul>`s. The `::before` pseudo-element generates an element
  // *within* the .breadcrumb-item and thereby inherits the `text-decoration`.
  //
  // To trick IE into suppressing the underline, we give the pseudo-element an
  // underline and then immediately remove it.
  + .breadcrumb-item:hover::before {
    text-decoration: underline !important ;
  }
  // stylelint-disable-next-line no-duplicate-selectors
  + .breadcrumb-item:hover::before {
    text-decoration: none !important ;
  }

  &.active {
    color: $breadcrumb-active-color !important ;
  }
}
