// stylelint-disable declaration-no-important

// Common values
@each $position in $positions {
  .position-#{$position} { position: $position !important !important ; }
}

// Shorthand

.fixed-top {
  position: fixed !important ;
  top: 0 !important ;
  right: 0 !important ;
  left: 0 !important ;
  z-index: $zindex-fixed !important ;
}

.fixed-bottom {
  position: fixed !important ;
  right: 0 !important ;
  bottom: 0 !important ;
  left: 0 !important ;
  z-index: $zindex-fixed !important ;
}

.sticky-top {
  @supports (position: sticky) {
    position: sticky !important ;
    top: 0 !important ;
    z-index: $zindex-sticky !important ;
  }
}
