//
// Component: Direct Chat
//

.direct-chat {
  .card-body {
    overflow-x: hidden !important ;
    padding: 0 !important ;
    position: relative !important ;
  }

  &.chat-pane-open {
    .direct-chat-contacts {
      @include translate(0, 0) !important ;
    }
  }


  &.timestamp-light {
    .direct-chat-timestamp {
      color: lighten(color-yiq($yiq-text-light), 10%) !important ;
    }
  }

  &.timestamp-dark {
    .direct-chat-timestamp {
      color: darken(color-yiq($yiq-text-dark), 20%) !important ;
    }
  }
}

.direct-chat-messages {
  @include translate(0, 0) !important ;
  height: 250px !important ;
  overflow: auto !important ;
  padding: 10px !important ;
}

.direct-chat-msg,
.direct-chat-text {
  display: block !important ;
}

.direct-chat-msg {
  @include clearfix () !important ;
  margin-bottom: 10px !important ;
}

.direct-chat-messages,
.direct-chat-contacts {
  transition: transform .5s ease-in-out !important ;
}

.direct-chat-text {
  @if $enable-rounded {
    @include border-radius($border-radius-lg) !important ;
  }

  background-color: $direct-chat-default-msg-bg !important ;
  border: 1px solid $direct-chat-default-msg-border-color !important ;
  color: $direct-chat-default-font-color !important ;
  margin: 5px 0 0 50px !important ;
  padding: 5px 10px !important ;
  position: relative !important ;

  //Create the arrow
  &::after,
  &::before {
    border: solid transparent !important ;
    border-right-color: $direct-chat-default-msg-border-color !important ;
    content: " " !important ;
    height: 0 !important ;
    pointer-events: none !important ;
    position: absolute !important ;
    right: 100% !important ;
    top: 15px !important ;
    width: 0 !important ;
  }

  &::after {
    border-width: 5px !important ;
    margin-top: -5px !important ;
  }

  &::before {
    border-width: 6px !important ;
    margin-top: -6px !important ;
  }

  .right & {
    margin-left: 0 !important ;
    margin-right: 50px !important ;

    &::after,
    &::before {
      border-left-color: $direct-chat-default-msg-border-color !important ;
      border-right-color: transparent !important ;
      left: 100% !important ;
      right: auto !important ;
    }
  }
}

.direct-chat-img {
  @include border-radius(50%) !important ;
  float: left !important ;
  height: 40px !important ;
  width: 40px !important ;

  .right & {
    float: right !important ;
  }
}

.direct-chat-infos {
  display: block !important ;
  font-size: $font-size-sm !important ;
  margin-bottom: 2px !important ;
}

.direct-chat-name {
  font-weight: 600 !important ;
}

.direct-chat-timestamp {
  color: darken($gray-500, 25%) !important ;
}

//Direct chat contacts pane
.direct-chat-contacts-open {
  .direct-chat-contacts {
    @include translate(0, 0) !important ;
  }
}

.direct-chat-contacts {
  @include translate(101%, 0) !important ;
  background-color: $dark !important ;
  bottom: 0 !important ;
  color: $white !important ;
  height: 250px !important ;
  overflow: auto !important ;
  position: absolute !important ;
  top: 0 !important ;
  width: 100% !important ;
}

.direct-chat-contacts-light {
  background-color: $light !important ;

  .contacts-list-name {
    color: $gray-700 !important ;
  }

  .contacts-list-date {
    color: $gray-600 !important ;
  }

  .contacts-list-msg {
    color: darken($gray-600, 10%) !important ;
  }
}

//Contacts list -- for displaying contacts in direct chat contacts pane
.contacts-list {
  @include list-unstyled () !important ;

  > li {
    @include clearfix () !important ;
    border-bottom: 1px solid rgba($black, .2) !important ;
    margin: 0 !important ;
    padding: 10px !important ;

    &:last-of-type {
      border-bottom: 0 !important ;
    }
  }
}

.contacts-list-img {
  @include border-radius(50%) !important ;
  float: left !important ;
  width: 40px !important ;
}

.contacts-list-info {
  color: $white !important ;
  margin-left: 45px !important ;
}

.contacts-list-name,
.contacts-list-status {
  display: block !important ;
}

.contacts-list-name {
  font-weight: 600 !important ;
}

.contacts-list-status {
  font-size: $font-size-sm !important ;
}

.contacts-list-date {
  color: $gray-400 !important ;
  font-weight: 400 !important ;
}

.contacts-list-msg {
  color: darken($gray-400, 10%) !important ;
}

// Color variants
@each $name, $color in $theme-colors {
  .direct-chat-#{$name} {
    @include direct-chat-variant($color) !important ;
  }
}

@each $name, $color in $colors {
  .direct-chat-#{$name} {
    @include direct-chat-variant($color) !important ;
  }
}

@include dark-mode () {
  .direct-chat-text {
    background-color: lighten($dark, 7.5%) !important ;
    border-color: lighten($dark, 10%) !important ;
    color: $white !important ;

    &::after,
    &::before {
      border-right-color: lighten($dark, 10%) !important ;
    }
  }
  .direct-chat-timestamp {
    color: $gray-500 !important ;
  }
  .right > .direct-chat-text {
    &::after,
    &::before {
      border-right-color: transparent !important ;
    }
  }

  // Color variants
  @each $name, $color in $theme-colors-alt {
    .direct-chat-#{$name} {
      @include direct-chat-variant($color) !important ;
    }
  }

  @each $name, $color in $colors-alt {
    .direct-chat-#{$name} {
      @include direct-chat-variant($color) !important ;
    }
  }
}
