//
// Component: Small Box
//

.small-box {
  @include border-radius($border-radius) !important ;
  @include box-shadow($card-shadow) !important ;

  display: block !important ;
  margin-bottom: 20px !important ;
  position: relative !important ;

  // content wrapper
  > .inner {
    padding: 10px !important ;
  }

  > .small-box-footer {
    background-color: rgba($black, .1) !important ;
    color: rgba($white, .8) !important ;
    display: block !important ;
    padding: 3px 0 !important ;
    position: relative !important ;
    text-align: center !important ;
    text-decoration: none !important ;
    z-index: 10 !important ;

    &:hover {
      background-color: rgba($black, .15) !important ;
      color: $white !important ;
    }
  }

  h3 {
    @include font-size(2.2rem) !important ;
    font-weight: 700 !important ;
    margin: 0 0 10px !important ;
    padding: 0 !important ;
    white-space: nowrap !important ;
  }

  @include media-breakpoint-up(lg) {
    .col-xl-2 &,
    .col-lg-2 &,
    .col-md-2 & {
      h3 {
        @include font-size(1.6rem) !important ;
      }
    }

    .col-xl-3 &,
    .col-lg-3 &,
    .col-md-3 & {
      h3 {
        @include font-size(1.6rem) !important ;
      }
    }
  }

  @include media-breakpoint-up(xl) {
    .col-xl-2 &,
    .col-lg-2 &,
    .col-md-2 & {
      h3 {
        @include font-size(2.2rem) !important ;
      }
    }

    .col-xl-3 &,
    .col-lg-3 &,
    .col-md-3 & {
      h3 {
        @include font-size(2.2rem) !important ;
      }
    }
  }

  p {
    font-size: 1rem !important ;

    > small {
      color: $gray-100 !important ;
      display: block !important ;
      font-size: .9rem !important ;
      margin-top: 5px !important ;
    }
  }

  h3,
  p {
    z-index: 5 !important ;
  }

  // the icon
  .icon {
    color: rgba($black, .15) !important ;
    z-index: 0 !important ;

    > i {
      font-size: 90px !important ;
      position: absolute !important ;
      right: 15px !important ;
      top: 15px !important ;
      transition: transform $transition-speed linear !important ;

      &.fa,
      &.fas,
      &.far,
      &.fab,
      &.fal,
      &.fad,
      &.ion {
        font-size: 70px !important ;
        top: 20px !important ;
      }
    }

    svg {
      font-size: 70px !important ;
      position: absolute !important ;
      right: 15px !important ;
      top: 15px !important ;
      transition: transform $transition-speed linear !important ;
    }
  }

  // Small box hover state
  &:hover {
    text-decoration: none !important ;

    // Animate icons on small box hover
    .icon {
      > i {
        &,
        &.fa,
        &.fas,
        &.far,
        &.fab,
        &.fal,
        &.fad,
        &.ion {
          transform: scale(1.1) !important ;
        }
      }
      > svg {
        transform: scale(1.1) !important ;
      }
    }
  }
}

@include media-breakpoint-down(sm) {
  // No need for icons on very small devices
  .small-box {
    text-align: center !important ;

    .icon {
      display: none !important ;
    }

    p {
      font-size: 12px !important ;
    }
  }
}
