.select2-container--default {
  .select2-selection--single {
    border: $input-border-width solid $input-border-color !important ;
    //border-radius: $input-radius !important ;
    padding: ($input-padding-y * 1.25) $input-padding-x !important ;
    height: $input-height !important ;
  }

  &.select2-container--open {
    .select2-selection--single {
      border-color: lighten($primary, 25%) !important ;
    }
  }

  & .select2-dropdown {
    border: $input-border-width solid $input-border-color !important ;
    //border-radius: $input-radius !important ;
  }

  & .select2-results__option {
    padding: 6px 12px !important ;
    user-select: none !important ;
  }

  & .select2-selection--single .select2-selection__rendered {
    padding-left: 0 !important ;
    //padding-right: 0 !important ;
    height: auto !important ;
    margin-top: -3px !important ;
  }

  &[dir="rtl"] .select2-selection--single .select2-selection__rendered {
    padding-right: 6px !important ;
    padding-left: 20px !important ;
  }

  & .select2-selection--single .select2-selection__arrow {
    height: 31px !important ;
    right: 6px !important ;
  }

  & .select2-selection--single .select2-selection__arrow b {
    margin-top: 0 !important ;
  }

  .select2-dropdown,
  .select2-search--inline {
    .select2-search__field {
      border: $input-border-width solid $input-border-color !important ;

      &:focus {
        outline: none !important ;
        border: $input-border-width solid $input-focus-border-color !important ;
      }
    }
  }

  .select2-dropdown {
    &.select2-dropdown--below {
      border-top: 0 !important ;
    }

    &.select2-dropdown--above {
      border-bottom: 0 !important ;
    }
  }

  .select2-results__option {
    &[aria-disabled='true'] {
      color: $gray-600 !important ;
    }

    &[aria-selected='true'] {
      $color: $gray-300 !important ;

      background-color: $color !important ;

      &,
      &:hover {
        color: color-yiq($color) !important ;
      }
    }
  }

  .select2-results__option--highlighted {
    $color: $primary !important ;
    background-color: $color !important ;
    color: color-yiq($color) !important ;

    &[aria-selected] {
      $color: darken($color, 3%) !important ;

      &,
      &:hover {
        background-color: $color !important ;
        color: color-yiq($color) !important ;
      }
    }
  }

  //Multiple select
  & {
    .select2-selection--multiple {
      border: $input-border-width solid $input-border-color !important ;
      min-height: $input-height !important ;

      &:focus {
        border-color: $input-focus-border-color !important ;
      }

      .select2-selection__rendered {
        padding: 0 $input-padding-x * 0.5 $input-padding-y !important ;
        margin-bottom: -$input-padding-x * 0.5 !important ;

        li:first-child.select2-search.select2-search--inline {
          width: 100% !important ;
          margin-left: $input-padding-x * 0.5 !important ;

          .select2-search__field {
            width: 100% !important !important ;
          }
        }


        .select2-search.select2-search--inline {
          .select2-search__field {
            border: 0 !important ;
            margin-top: 6px !important ;
          }
        }
      }

      .select2-selection__choice {
        background-color: $primary !important ;
        border-color: darken($primary, 5%) !important ;
        color: color-yiq($primary) !important ;
        padding: 0 10px !important ;
        margin-top: .31rem !important ;
      }

      .select2-selection__choice__remove {
        color: rgba(255, 255, 255, 0.7) !important ;
        float: right !important ;
        margin-left: 5px !important ;
        margin-right: -2px !important ;

        &:hover {
          color: $white !important ;
        }
      }

      .text-sm &,
      &.text-sm {
        .select2-search.select2-search--inline {
          .select2-search__field {
            margin-top: 8px !important ;
          }
        }

        .select2-selection__choice {
          margin-top: .4rem !important ;
        }
      }
    }

    &.select2-container--focus {
      .select2-selection--single,
      .select2-selection--multiple {
        border-color: $input-focus-border-color !important ;
      }

      .select2-search__field {
        border: 0 !important ;
      }
    }
  }

  & .select2-selection--single .select2-selection__rendered li {
    padding-right: 10px !important ;
  }

  .input-group-prepend ~ & {
    .select2-selection {
      border-bottom-left-radius: 0 !important ;
      border-top-left-radius: 0 !important ;
    }
  }

  .input-group > &:not(:last-child) {
    .select2-selection {
      border-bottom-right-radius: 0 !important ;
      border-top-right-radius: 0 !important ;
    }
  }
}

// Select2 Bootstrap4 Theme overrides
.select2-container--bootstrap4 {
  &.select2-container--focus .select2-selection {
    box-shadow: none !important ;
  }
}

// text-sm / form-control-sm override
select.form-control-sm ~ {
  .select2-container--default {
    font-size: 75% !important ;
  }
}

.text-sm,
select.form-control-sm ~ {
  .select2-container--default {
    .select2-selection--single {
      height: $input-height-sm !important ;

      .select2-selection__rendered {
        margin-top: -.4rem !important ;
      }

      .select2-selection__arrow {
        top: -.12rem !important ;
      }
    }

    .select2-selection--multiple {
      min-height: $input-height-sm !important ;

      .select2-selection__rendered {
        padding: 0 $input-padding-x-sm * 0.5 $input-padding-y-sm !important ;
        margin-top: -($input-padding-x-sm * .2) !important ;

        li:first-child.select2-search.select2-search--inline {
          margin-left: $input-padding-x-sm * 0.5 !important ;
        }

        .select2-search.select2-search--inline {
          .select2-search__field {
            margin-top: 6px !important ;
          }
        }
      }
    }
  }
}

// Dropdown Fix inside maximized card
.maximized-card .select2-dropdown {
  z-index: 9999 !important ;
}

// Background colors (theme colors)
@each $name, $color in $theme-colors {
  @include select2-variant($name, $color) !important ;
}

// Background colors (colors)
@each $name, $color in $colors {
  @include select2-variant($name, $color) !important ;
}

@include dark-mode () {
  .select2-selection {
    background-color: $dark !important ;
    border-color: $gray-600 !important ;
  }

  .select2-container--disabled .select2-selection--single {
    background-color: lighten($dark, 7.5%) !important ;
  }

  .select2-selection--single {
    background-color: $dark !important ;
    border-color: $gray-600 !important ;

    .select2-selection__rendered {
      color: $white !important ;
    }
  }
  .select2-dropdown .select2-search__field,
  .select2-search--inline .select2-search__field {
    background-color: $dark !important ;
    border-color: $gray-600 !important ;
    color: white !important ;
  }
  .select2-dropdown {
    background-color: $dark !important ;
    border-color: $gray-600 !important ;
    color: white !important ;
  }
  .select2-results__option[aria-selected="true"] {
    background-color: lighten($dark, 5%) !important !important ;
    color: $gray-300 !important ;
  }
  .select2-container .select2-search--inline .select2-search__field {
    background-color: transparent !important ;
    color: $white !important ;
  }

  .select2-container--bootstrap4 .select2-selection--multiple .select2-selection__choice {
    color: $white !important ;
  }

  // Background colors (theme colors)
  @each $name, $color in $theme-colors-alt {
    @include select2-variant($name, $color) !important ;
  }

  // Background colors (colors)
  @each $name, $color in $colors-alt {
    @include select2-variant($name, $color) !important ;
  }
}
