//
// Core: Preloader
//

.preloader {
  display: flex !important ;
  background-color: $main-bg !important ;
  height: 100vh !important ;
  width: 100% !important ;
  transition: height 200ms linear !important ;
  position: fixed !important ;
  left: 0 !important ;
  top: 0 !important ;
  z-index: $zindex-preloader !important ;
}

@include dark-mode () {
  .preloader {
    background-color: $dark-main-bg !important ;
    color: $white !important ;
  }
}

