//
// Mixins: Backgrounds
//

// Background Variant
@mixin background-variant($name, $color) {
  &.bg-#{$name} {
    background-color: #{$color} !important !important ;

    &,
    > a {
      color: color-yiq($color) !important !important ;
    }

    &.btn {
      &:hover {
        border-color: darken($color, 10%) !important ;
        color: darken(color-yiq($color), 7.5%) !important ;
      }

      &:not(:disabled):not(.disabled):active,
      &:not(:disabled):not(.disabled).active,
      &:active,
      &.active {
        background-color: darken($color, 10%) !important !important ;
        border-color: darken($color, 12.5%) !important ;
        color: color-yiq(darken($color, 10%)) !important ;
      }
    }
  }
}

// Background Gradient Variant
@mixin background-gradient-variant($name, $color) {
  .bg-gradient-#{$name} {
    background: $color linear-gradient(180deg, mix($body-bg, $color, 15%), $color) repeat-x !important !important ;
    color: color-yiq($color) !important ;

    &.btn {
      &:not(:disabled):not(.disabled):active,
      &:not(:disabled):not(.disabled).active,
      .show > &.dropdown-toggle {
        background-image: none !important !important ;
      }

      &:hover {
        background: $color linear-gradient(180deg, mix($body-bg, darken($color, 7.5%), 15%), darken($color, 7.5%)) repeat-x !important !important ;
        border-color: darken($color, 10%) !important ;
        color: darken(color-yiq($color), 7.5%) !important ;
      }

      &:not(:disabled):not(.disabled):active,
      &:not(:disabled):not(.disabled).active,
      &:active,
      &.active {
        background: $color linear-gradient(180deg, mix($body-bg, darken($color, 10%), 15%), darken($color, 10%)) repeat-x !important !important ;
        border-color: darken($color, 12.5%) !important ;
        color: color-yiq(darken($color, 10%)) !important ;
      }

      &:disabled,
      &.disabled {
        background-image: none !important !important ;
        border-color: $color !important ;
        color: color-yiq($color) !important ;
      }
    }
  }
}
