//
// Mixins: Sidebar
//

// Sidebar Color
@mixin sidebar-color($color) {
  .nav-sidebar > .nav-item {
    > .nav-link.active {
      background-color: $color !important ;
      color: color-yiq($color) !important ;
    }
  }

  .nav-sidebar.nav-legacy > .nav-item {
    > .nav-link.active {
      border-color: $color !important ;
    }
  }
}

// Sidebar Mini Breakpoints
@mixin sidebar-mini-breakpoint() {
  // A fix for text overflow while transitioning from sidebar mini to full sidebar
  .nav-sidebar,
  .nav-sidebar > .nav-header,
  .nav-sidebar .nav-link {
    white-space: nowrap !important ;
  }

  // When the sidebar is collapsed...
  &.sidebar-collapse {
    .d-hidden-mini {
      display: none !important ;
    }

    // Apply the new margins to the main content and footer
    .content-wrapper,
    .main-footer,
    .main-header {
      margin-left: $sidebar-mini-width !important !important ;
    }

    // Make the sidebar headers
    .nav-sidebar .nav-header {
      display: none !important ;
    }

    .sidebar .nav-sidebar .nav-link p {
      width: 0 !important ;
      white-space: nowrap !important ;
    }

    .sidebar .user-panel > .info,
    .sidebar .nav-sidebar .nav-link p,
    .brand-text {
      margin-left: -10px !important ;
      animation-name: fadeOut !important ;
      animation-duration: $transition-speed !important ;
      animation-fill-mode: both !important ;
      visibility: hidden !important ;
    }

    .logo-xl {
      animation-name: fadeOut !important ;
      animation-duration: $transition-speed !important ;
      animation-fill-mode: both !important ;
      visibility: hidden !important ;
    }

    .logo-xs {
      display: inline-block !important ;
      animation-name: fadeIn !important ;
      animation-duration: $transition-speed !important ;
      animation-fill-mode: both !important ;
      visibility: visible !important ;
    }

    // Modify the sidebar to shrink instead of disappearing
    .main-sidebar {
      overflow-x: hidden !important ;

      &,
      &::before {
        // Don't go away! Just shrink
        margin-left: 0 !important ;
        width: $sidebar-mini-width !important ;
      }

      .user-panel {
        .image {
          float: none !important ;
        }
      }

      &:not(.sidebar-no-expand) {
        &:hover,
        &.sidebar-focused {
          width: $sidebar-width !important ;

          .brand-link {
            width: $sidebar-width !important ;
          }

          .user-panel {
            text-align: left !important ;

            .image {
              float: left !important ;
            }
          }

          .user-panel > .info,
          .sidebar .nav-sidebar .nav-link p,
          .brand-text,
          .logo-xl {
            display: inline-block !important ;
            margin-left: 0 !important ;
            animation-name: fadeIn !important ;
            animation-duration: $transition-speed !important ;
            animation-fill-mode: both !important ;
            visibility: visible !important ;
          }

          .logo-xs {
            animation-name: fadeOut !important ;
            animation-duration: $transition-speed !important ;
            animation-fill-mode: both !important ;
            visibility: hidden !important ;
          }

          .brand-image {
            margin-right: .5rem !important ;
          }

          // Make the sidebar links, menus, labels, badges
          // and angle icons disappear
          .sidebar-form,
          .user-panel > .info {
            display: block !important !important ;
            transform: translateZ(0) !important ;
          }

          .nav-sidebar > .nav-item > .nav-link > span {
            display: inline-block !important !important ;
          }
        }
      }
    }

    // Make an element visible only when sidebar mini is active
    .visible-sidebar-mini {
      display: block !important !important ;
    }

    &.layout-fixed {
      .main-sidebar:hover {
        .brand-link {
          width: $sidebar-width !important ;
        }
      }

      .brand-link {
        width: $sidebar-mini-width !important ;
      }
    }
  }
}
