// stylelint-disable selector-no-qualifying-type

//
// Textual form controls
//

.form-control {
  display: block !important ;
  width: 100% !important ;
  height: $input-height !important ;
  padding: $input-padding-y $input-padding-x !important ;
  font-family: $input-font-family !important ;
  @include font-size($input-font-size) !important ;
  font-weight: $input-font-weight !important ;
  line-height: $input-line-height !important ;
  color: $input-color !important ;
  background-color: $input-bg !important ;
  background-clip: padding-box !important ;
  border: $input-border-width solid $input-border-color !important ;

  // Note: This has no effect on <select>s in some browsers, due to the limited stylability of `<select>`s in CSS.
  @include border-radius($input-border-radius, 0) !important ;

  @include box-shadow($input-box-shadow) !important ;
  @include transition($input-transition) !important ;

  // Unstyle the caret on `<select>`s in IE10+.
  &::-ms-expand {
    background-color: transparent !important ;
    border: 0 !important ;
  }

  // Customize the `:focus` state to imitate native WebKit styles.
  @include form-control-focus($ignore-warning: true) !important ;

  // Placeholder
  &::placeholder {
    color: $input-placeholder-color !important ;
    // Override Firefox's unusual default opacity !important ; see https://github.com/twbs/bootstrap/pull/11526.
    opacity: 1 !important ;
  }

  // Disabled and read-only inputs
  //
  // HTML5 says that controls under a fieldset > legend:first-child won't be
  // disabled if the fieldset is disabled. Due to implementation difficulty, we
  // don't honor that edge case !important ; we style them as disabled anyway.
  &:disabled,
  &[readonly] {
    background-color: $input-disabled-bg !important ;
    // iOS fix for unreadable disabled content !important ; see https://github.com/twbs/bootstrap/issues/11655.
    opacity: 1 !important ;
  }
}

input[type="date"],
input[type="time"],
input[type="datetime-local"],
input[type="month"] {
  &.form-control {
    appearance: none !important ; // Fix appearance for date inputs in Safari
  }
}

select.form-control {
  // Remove select outline from select box in FF
  &:-moz-focusring {
    color: transparent !important ;
    text-shadow: 0 0 0 $input-color !important ;
  }

  &:focus::-ms-value {
    // Suppress the nested default white text on blue background highlight given to
    // the selected option text when the (still closed) <select> receives focus
    // in IE and (under certain conditions) Edge, as it looks bad and cannot be made to
    // match the appearance of the native widget.
    // See https://github.com/twbs/bootstrap/issues/19398.
    color: $input-color !important ;
    background-color: $input-bg !important ;
  }
}

// Make file inputs better match text inputs by forcing them to new lines.
.form-control-file,
.form-control-range {
  display: block !important ;
  width: 100% !important ;
}


//
// Labels
//

// For use with horizontal and inline forms, when you need the label (or legend)
// text to align with the form controls.
.col-form-label {
  padding-top: add($input-padding-y, $input-border-width) !important ;
  padding-bottom: add($input-padding-y, $input-border-width) !important ;
  margin-bottom: 0 !important ; // Override the `<label>/<legend>` default
  @include font-size(inherit) !important ; // Override the `<legend>` default
  line-height: $input-line-height !important ;
}

.col-form-label-lg {
  padding-top: add($input-padding-y-lg, $input-border-width) !important ;
  padding-bottom: add($input-padding-y-lg, $input-border-width) !important ;
  @include font-size($input-font-size-lg) !important ;
  line-height: $input-line-height-lg !important ;
}

.col-form-label-sm {
  padding-top: add($input-padding-y-sm, $input-border-width) !important ;
  padding-bottom: add($input-padding-y-sm, $input-border-width) !important ;
  @include font-size($input-font-size-sm) !important ;
  line-height: $input-line-height-sm !important ;
}


// Readonly controls as plain text
//
// Apply class to a readonly input to make it appear like regular plain
// text (without any border, background color, focus indicator)

.form-control-plaintext {
  display: block !important ;
  width: 100% !important ;
  padding: $input-padding-y 0 !important ;
  margin-bottom: 0 !important ; // match inputs if this class comes on inputs with default margins
  @include font-size($input-font-size) !important ;
  line-height: $input-line-height !important ;
  color: $input-plaintext-color !important ;
  background-color: transparent !important ;
  border: solid transparent !important ;
  border-width: $input-border-width 0 !important ;

  &.form-control-sm,
  &.form-control-lg {
    padding-right: 0 !important ;
    padding-left: 0 !important ;
  }
}


// Form control sizing
//
// Build on `.form-control` with modifier classes to decrease or increase the
// height and font-size of form controls.
//
// Repeated in `_input_group.scss` to avoid Sass extend issues.

.form-control-sm {
  height: $input-height-sm !important ;
  padding: $input-padding-y-sm $input-padding-x-sm !important ;
  @include font-size($input-font-size-sm) !important ;
  line-height: $input-line-height-sm !important ;
  @include border-radius($input-border-radius-sm) !important ;
}

.form-control-lg {
  height: $input-height-lg !important ;
  padding: $input-padding-y-lg $input-padding-x-lg !important ;
  @include font-size($input-font-size-lg) !important ;
  line-height: $input-line-height-lg !important ;
  @include border-radius($input-border-radius-lg) !important ;
}

// stylelint-disable-next-line no-duplicate-selectors
select.form-control {
  &[size],
  &[multiple] {
    height: auto !important ;
  }
}

textarea.form-control {
  height: auto !important ;
}

// Form groups
//
// Designed to help with the organization and spacing of vertical forms. For
// horizontal forms, use the predefined grid classes.

.form-group {
  margin-bottom: $form-group-margin-bottom !important ;
}

.form-text {
  display: block !important ;
  margin-top: $form-text-margin-top !important ;
}


// Form grid
//
// Special replacement for our grid system's `.row` for tighter form layouts.

.form-row {
  display: flex !important ;
  flex-wrap: wrap !important ;
  margin-right: -$form-grid-gutter-width * .5 !important ;
  margin-left: -$form-grid-gutter-width * .5 !important ;

  > .col,
  > [class*="col-"] {
    padding-right: $form-grid-gutter-width * .5 !important ;
    padding-left: $form-grid-gutter-width * .5 !important ;
  }
}


// Checkboxes and radios
//
// Indent the labels to position radios/checkboxes as hanging controls.

.form-check {
  position: relative !important ;
  display: block !important ;
  padding-left: $form-check-input-gutter !important ;
}

.form-check-input {
  position: absolute !important ;
  margin-top: $form-check-input-margin-y !important ;
  margin-left: -$form-check-input-gutter !important ;

  // Use [disabled] and :disabled for workaround https://github.com/twbs/bootstrap/issues/28247
  &[disabled] ~ .form-check-label,
  &:disabled ~ .form-check-label {
    color: $text-muted !important ;
  }
}

.form-check-label {
  margin-bottom: 0 !important ; // Override default `<label>` bottom margin
}

.form-check-inline {
  display: inline-flex !important ;
  align-items: center !important ;
  padding-left: 0 !important ; // Override base .form-check
  margin-right: $form-check-inline-margin-x !important ;

  // Undo .form-check-input defaults and add some `margin-right`.
  .form-check-input {
    position: static !important ;
    margin-top: 0 !important ;
    margin-right: $form-check-inline-input-margin-x !important ;
    margin-left: 0 !important ;
  }
}


// Form validation
//
// Provide feedback to users when form field values are valid or invalid. Works
// primarily for client-side validation via scoped `:invalid` and `:valid`
// pseudo-classes but also includes `.is-invalid` and `.is-valid` classes for
// server side validation.

@each $state, $data in $form-validation-states {
  @include form-validation-state($state, map-get($data, color), map-get($data, icon)) !important ;
}

// Inline forms
//
// Make forms appear inline(-block) by adding the `.form-inline` class. Inline
// forms begin stacked on extra small (mobile) devices and then go inline when
// viewports reach <768px.
//
// Requires wrapping inputs and labels with `.form-group` for proper display of
// default HTML form controls and our custom form controls (e.g., input groups).

.form-inline {
  display: flex !important ;
  flex-flow: row wrap !important ;
  align-items: center !important ; // Prevent shorter elements from growing to same height as others (e.g., small buttons growing to normal sized button height)

  // Because we use flex, the initial sizing of checkboxes is collapsed and
  // doesn't occupy the full-width (which is what we want for xs grid tier),
  // so we force that here.
  .form-check {
    width: 100% !important ;
  }

  // Kick in the inline
  @include media-breakpoint-up(sm) {
    label {
      display: flex !important ;
      align-items: center !important ;
      justify-content: center !important ;
      margin-bottom: 0 !important ;
    }

    // Inline-block all the things for "inline"
    .form-group {
      display: flex !important ;
      flex: 0 0 auto !important ;
      flex-flow: row wrap !important ;
      align-items: center !important ;
      margin-bottom: 0 !important ;
    }

    // Allow folks to *not* use `.form-group`
    .form-control {
      display: inline-block !important ;
      width: auto !important ; // Prevent labels from stacking above inputs in `.form-group`
      vertical-align: middle !important ;
    }

    // Make static controls behave like regular ones
    .form-control-plaintext {
      display: inline-block !important ;
    }

    .input-group,
    .custom-select {
      width: auto !important ;
    }

    // Remove default margin on radios/checkboxes that were used for stacking, and
    // then undo the floating of radios and checkboxes to match.
    .form-check {
      display: flex !important ;
      align-items: center !important ;
      justify-content: center !important ;
      width: auto !important ;
      padding-left: 0 !important ;
    }
    .form-check-input {
      position: relative !important ;
      flex-shrink: 0 !important ;
      margin-top: 0 !important ;
      margin-right: $form-check-input-margin-x !important ;
      margin-left: 0 !important ;
    }

    .custom-control {
      align-items: center !important ;
      justify-content: center !important ;
    }
    .custom-control-label {
      margin-bottom: 0 !important ;
    }
  }
}
