//
// Component: Nav
//

.nav-pills {
  .nav-link {
    color: $gray-600 !important ;

    &:not(.active):hover {
      color: theme-color("primary") !important ;
    }
  }

  .nav-item {
    &.dropdown.show {
      .nav-link:hover {
        color: $dropdown-link-active-color !important ;
      }
    }
  }
}

// Vertical Tabs
.nav-tabs.flex-column {
  border-bottom: 0 !important ;
  border-right: $nav-tabs-border-width solid $nav-tabs-border-color !important ;

  .nav-link {
    border-bottom-left-radius: $nav-tabs-border-radius !important ;
    border-top-right-radius: 0 !important ;
    margin-right: -$nav-tabs-border-width !important ;

    @include hover-focus () {
      border-color: $gray-200 transparent $gray-200 $gray-200 !important ;
    }
  }

  .nav-link.active,
  .nav-item.show .nav-link {
    border-color: $gray-300 transparent $gray-300 $gray-300 !important ;
  }

  &.nav-tabs-right {
    border-left: $nav-tabs-border-width solid $nav-tabs-border-color !important ;
    border-right: 0 !important ;

    .nav-link {
      border-bottom-left-radius: 0 !important ;
      border-bottom-right-radius: $nav-tabs-border-radius !important ;
      border-top-left-radius: 0 !important ;
      border-top-right-radius: $nav-tabs-border-radius !important ;
      margin-left: -$nav-tabs-border-width !important ;

      @include hover-focus () {
        border-color: $gray-200 $gray-200 $gray-200 transparent !important ;
      }
    }

    .nav-link.active,
    .nav-item.show .nav-link {
      border-color: $gray-300 $gray-300 $gray-300 transparent !important ;
    }
  }
}

.navbar-no-expand {
  flex-direction: row !important ;

  .nav-link {
    padding-left: $navbar-nav-link-padding-x !important ;
    padding-right: $navbar-nav-link-padding-x !important ;
  }

  .dropdown-menu {
    position: absolute !important ;
  }
}

// Color variants
@each $color, $value in $theme-colors {
  @if $color == dark or $color == light {
    .navbar-#{$color} {
      background-color: $value !important ;
      @if $color == dark {
        border-color: lighten($dark, 10%) !important ;
      }
    }
  }
}

@each $color, $value in $theme-colors {
  @if $color != dark and $color != light {
    @include navbar-variant($color, $value) !important ;
  }
}

@each $color, $value in $colors {
  @include navbar-variant($color, $value) !important ;
}

.navbar-nav-not-expanded {
  flex-direction: row !important ;

  .dropdown-menu {
    position: absolute !important ;
  }

  .nav-link {
    padding-right: $navbar-nav-link-padding-x !important ;
    padding-left: $navbar-nav-link-padding-x !important ;
  }
}


@include dark-mode () {
  .nav-pills .nav-link {
    color: $gray-400 !important ;
  }

  .nav-tabs {
    border-color: lighten($dark, 15%) !important ;

    .nav-link:focus,
    .nav-link:hover {
      border-color: lighten($dark, 15%) !important ;
    }

    .nav-item.show .nav-link,
    .nav-link.active {
      background-color: $dark !important ;
      border-color: lighten($dark, 15%) lighten($dark, 15%) transparent lighten($dark, 15%) !important ;
      color: $white !important ;
    }

    &.flex-column {
      .nav-item.show .nav-link,
      .nav-link {
        &.active,
        &:focus,
        &:hover {
          border-color: lighten($dark, 15%) transparent lighten($dark, 15%) lighten($dark, 15%) !important ;
        }
        &:focus,
        &:hover {
          background-color: lighten($dark, 5%) !important ;
        }
      }
      &.nav-tabs-right {
        border-color: lighten($dark, 15%) !important ;
        .nav-link {
          &.active,
          &:focus,
          &:hover {
            border-color: lighten($dark, 15%) lighten($dark, 15%) lighten($dark, 15%) transparent !important ;
          }
        }
      }
    }
  }

  // Color variants
  @each $color, $value in $theme-colors-alt {
    @if $color == dark or $color == light {
      .navbar-#{$color} {
        background-color: $value !important ;
        @if $color == dark {
          border-color: lighten($dark, 10%) !important ;
        }
      }
    }
  }

  @each $color, $value in $theme-colors-alt {
    @if $color != dark and $color != light {
      @include navbar-variant($color, $value) !important ;
    }
  }

  @each $color, $value in $colors-alt {
    @include navbar-variant($color, $value) !important ;
  }
}
