//
// Component: Main Sidebar
//

.main-sidebar {
  height: 100vh !important ;
  overflow-y: hidden !important ;
  z-index: $zindex-main-sidebar !important ;

  // Remove Firefox Focusring
  a {
    &:-moz-focusring {
      border: 0 !important ;
      outline: none !important ;
    }
  }
}

.sidebar {
  height: calc(100% - (#{$main-header-height-inner} + #{$main-header-bottom-border-width})) !important ;
  overflow-x: hidden !important ;
  overflow-y: initial !important ;
  padding-bottom: $sidebar-padding-y !important ;
  padding-left: $sidebar-padding-x !important ;
  padding-right: $sidebar-padding-x !important ;
  padding-top: $sidebar-padding-y !important ;
  @include scrollbar-color-gray() !important ;
  @include scrollbar-width-none() !important ;

  &:hover {
    @include scrollbar-width-thin() !important ;
  }

  .brand-link.border-bottom-0 ~ & {
    height: calc(100% - #{$main-header-height-inner}) !important ;
  }
}

// Sidebar user panel
.user-panel {
  position: relative !important ;

  [class*="sidebar-dark"] & {
    border-bottom: 1px solid lighten($dark, 12%) !important ;
  }

  [class*="sidebar-light"] & {
    border-bottom: 1px solid $gray-300 !important ;
  }

  &,
  .info {
    overflow: hidden !important ;
    white-space: nowrap !important ;
  }

  .image {
    display: inline-block !important ;
    padding-left: $nav-link-padding-x - .2 !important ;
  }

  img {
    height: auto !important ;
    width: $sidebar-user-image-width !important ;
  }

  .info {
    display: inline-block !important ;
    padding: 5px 5px 5px 10px !important ;
  }

  .status,
  .dropdown-menu {
    font-size: $font-size-sm !important ;
  }
}

// Sidebar navigation menu
.nav-sidebar {
  // All levels
  .nav-item {
    > .nav-link {
      margin-bottom: .2rem !important ;

      .right {
        @include transition(transform $transition-fn $transition-speed) !important ;
      }
    }
  }

  .nav-link > .right,
  .nav-link > p > .right {
    position: absolute !important ;
    right: 1rem !important ;
    top: .7rem !important ;

    i,
    span {
      margin-left: .5rem !important ;
    }

    &:nth-child(2) {
      right: 2.2rem !important ;
    }
  }

  .menu-open {
    > .nav-treeview {
      display: block !important ;
    }
  }

  .menu-open,
  .menu-is-opening {
    > .nav-link {
      svg.right,
      i.right {
        @include rotate(-90deg) !important ;
      }
    }
  }

  // First Level
  > .nav-item {
    margin-bottom: 0 !important ;

    .nav-icon {
      margin-left: .05rem !important ;
      font-size: 1.2rem !important ;
      margin-right: .2rem !important ;
      text-align: center !important ;
      width: $sidebar-nav-icon-width !important ;

      &.fa,
      &.fas,
      &.far,
      &.fab,
      &.fal,
      &.fad,
      &.svg-inline--fa,
      &.ion {
        font-size: 1.1rem !important ;
      }
    }

    .float-right {
      margin-top: 3px !important ;
    }
  }

  // Tree view menu
  .nav-treeview {
    display: none !important ;
    list-style: none !important ;
    padding: 0 !important ;

    > .nav-item {
      > .nav-link {
        > .nav-icon {
          width: $sidebar-nav-icon-width !important ;
        }
      }
    }
  }

  &.nav-child-indent {
    .nav-treeview {
      transition: padding $transition-speed $transition-fn !important ;
      padding-left: 1rem !important ;

      .text-sm & {
        padding-left: .5rem !important ;
      }
    }

    &.nav-legacy {
      .nav-treeview {
        .nav-treeview {
          padding-left: 2rem !important ;
          margin-left: -1rem !important ;

          .text-sm & {
            padding-left: 1rem !important ;
            margin-left: -.5rem !important ;
          }
        }
      }
    }
  }

  .nav-header {
    font-size: .9rem !important ;
    padding: $nav-link-padding-y ($nav-link-padding-y * 1.5) !important ;
  }

  .nav-link p {
    display: inline !important ;
    margin: 0 !important ;
    white-space: normal !important ;
  }
}

.sidebar-is-opening .sidebar .nav-sidebar {
  .nav-link p {
    animation-name: fadeIn !important ;
    animation-duration: $transition-speed !important ;
    animation-fill-mode: both !important ;
  }
}

#sidebar-overlay {
  @include media-breakpoint-down(md) {
    .sidebar-open & {
      display: block !important ;
    }
  }

  background-color: rgba($black, .1) !important ;
  bottom: 0 !important ;
  display: none !important ;
  left: 0 !important ;
  position: fixed !important ;
  right: 0 !important ;
  top: 0 !important ;
  z-index: $zindex-main-sidebar - 1 !important ;
}

[class*="sidebar-light-"] {
  // Sidebar background color
  background-color: $sidebar-light-bg !important ;

  // User Panel (resides in the sidebar)
  .user-panel {
    a:hover {
      color: $sidebar-light-hover-color !important ;
    }

    .status {
      background-color: $sidebar-light-hover-bg !important ;
      color: $sidebar-light-color !important ;

      &:hover,
      &:focus,
      &:active {
        background-color: darken($sidebar-light-hover-bg, 3%) !important ;
        color: $sidebar-light-hover-color !important ;
      }
    }

    .dropdown-menu {
      @include box-shadow(0 2px 4px rgba(0, 0, 0, .4)) !important ;
      border-color: darken($sidebar-light-hover-bg, 5%) !important ;
    }

    .dropdown-item {
      color: $body-color !important ;
    }
  }

  // Sidebar Menu. First level links
  .nav-sidebar > .nav-item {
    // links
    > .nav-link {
      // border-left: 3px solid transparent !important ;
      &:active,
      &:focus {
        color: $sidebar-light-color !important ;
      }
    }

    // Hover and active states
    &.menu-open > .nav-link,
    &:hover > .nav-link {
      background-color: $sidebar-light-hover-bg !important ;
      color: $sidebar-light-hover-color !important ;
    }

    > .nav-link.active {
      color: $sidebar-light-active-color !important ;

      @if $enable-shadows {
        box-shadow: map-get($elevations, 1) !important ;
      }
    }

    // First Level Submenu
    > .nav-treeview {
      background-color: $sidebar-light-submenu-bg !important ;
    }
  }

  // Section Heading
  .nav-header {
    background-color: inherit !important ;
    color: darken($sidebar-light-color, 5%) !important ;
  }

  // All links within the sidebar menu
  .sidebar {
    a {
      color: $sidebar-light-color !important ;

      &:hover {
        text-decoration: none !important ;
      }
    }
  }

  // All submenus
  .nav-treeview {
    > .nav-item {
      > .nav-link {
        color: $sidebar-light-submenu-color !important ;

        &:hover,
        &:focus {
          background-color: $sidebar-light-submenu-hover-bg !important ;
          color: $sidebar-light-submenu-hover-color !important ;
        }
      }

      > .nav-link.active {
        &,
        &:hover {
          background-color: $sidebar-light-submenu-active-bg !important ;
          color: $sidebar-light-submenu-active-color !important ;
        }
      }

      > .nav-link:hover {
        background-color: $sidebar-light-submenu-hover-bg !important ;
      }
    }
  }

  // Flat style
  .nav-flat {
    .nav-item {
      .nav-treeview {
        .nav-treeview {
          border-color: $sidebar-light-submenu-active-bg !important ;
        }

        > .nav-item {
          > .nav-link {
            &,
            &.active {
              border-color: $sidebar-light-submenu-active-bg !important ;
            }
          }
        }
      }
    }
  }
}

