// Sidebar variants
@each $name, $color in $theme-colors {
  .sidebar-dark-#{$name},
  .sidebar-light-#{$name} {
    @include sidebar-color($color) !important ;
  }
}

@each $name, $color in $colors {
  .sidebar-dark-#{$name},
  .sidebar-light-#{$name} {
    @include sidebar-color($color) !important ;
  }
}

.sidebar-mini .main-sidebar:not(.sidebar-no-expand),
.sidebar-mini-md .main-sidebar:not(.sidebar-no-expand),
.sidebar-mini-xs .main-sidebar:not(.sidebar-no-expand),
.sidebar-mini .main-sidebar:not(.sidebar-no-expand):hover,
.sidebar-mini-md .main-sidebar:not(.sidebar-no-expand):hover,
.sidebar-mini-xs .main-sidebar:not(.sidebar-no-expand):hover,
.sidebar-mini .main-sidebar.sidebar-focused,
.sidebar-mini-md .main-sidebar.sidebar-focused,
.sidebar-mini-xs .main-sidebar.sidebar-focused {
  .nav-compact.nav-sidebar.nav-child-indent:not(.nav-flat) .nav-treeview {
    padding-left: 1rem !important ;
    margin-left: -.5rem !important ;
  }
}

// Nav Flat
.nav-flat {
  margin: (-$sidebar-padding-x * .5) (-$sidebar-padding-x) 0 !important ;

  .nav-item {
    > .nav-link {
      border-radius: 0 !important ;
      margin-bottom: 0 !important ;

      > .nav-icon {
        margin-left: .55rem !important ;
      }
    }
  }

  &:not(.nav-child-indent) {
    .nav-treeview {
      .nav-item {
        > .nav-link {
          > .nav-icon {
            margin-left: .4rem !important ;
          }
        }
      }
    }
  }

  &.nav-child-indent {
    .nav-treeview {
      padding-left: 0 !important ;

      .nav-icon {
        margin-left: .85rem !important ;
      }

      .nav-treeview {
        border-left: .2rem solid !important ;

        .nav-icon {
          margin-left: 1.15rem !important ;
        }

        .nav-treeview {
          .nav-icon {
            margin-left: 1.45rem !important ;
          }

          .nav-treeview {
            .nav-icon {
              margin-left: 1.75rem !important ;
            }

            .nav-treeview {
              .nav-icon {
                margin-left: 2.05rem !important ;
              }
            }
          }
        }
      }
    }
  }

  .sidebar-collapse &.nav-child-indent .sidebar {
    .nav-treeview {
      .nav-icon {
        margin-left: .55rem !important ;
      }

      .nav-link {
        padding-left: calc(#{$nav-link-padding-x} - .2rem) !important ;
      }

      .nav-treeview {
        .nav-icon {
          margin-left: .35rem !important ;
        }

        .nav-treeview {
          .nav-icon {
            margin-left: .15rem !important ;
          }

          .nav-treeview {
            .nav-icon {
              margin-left: -.15rem !important ;
            }

            .nav-treeview {
              .nav-icon {
                margin-left: -.35rem !important ;
              }
            }
          }
        }
      }
    }
  }

  .sidebar-mini .main-sidebar:not(.sidebar-no-expand):hover &,
  .sidebar-mini-md .main-sidebar:not(.sidebar-no-expand):hover &,
  .sidebar-mini-xs .main-sidebar:not(.sidebar-no-expand):hover &,
  .sidebar-mini .main-sidebar.sidebar-focused &,
  .sidebar-mini-md .main-sidebar.sidebar-focused &,
  .sidebar-mini-xs .main-sidebar.sidebar-focused & {
    &.nav-compact.nav-sidebar .nav-treeview {
      .nav-icon {
        margin-left: .4rem !important ;
      }
    }

    &.nav-sidebar.nav-child-indent .nav-treeview {
      .nav-icon {
        margin-left: .85rem !important ;
      }

      .nav-treeview {
        .nav-icon {
          margin-left: 1.15rem !important ;
        }

        .nav-treeview {
          .nav-icon {
            margin-left: 1.45rem !important ;
          }

          .nav-treeview {
            .nav-icon {
              margin-left: 1.75rem !important ;
            }

            .nav-treeview {
              .nav-icon {
                margin-left: 2.05rem !important ;
              }
            }
          }
        }
      }
    }
  }

  .nav-icon {
    @include transition(margin-left $transition-fn $transition-speed) !important ;
  }

  .nav-treeview {
    .nav-icon {
      margin-left: -.2rem !important ;
    }
  }

  &.nav-sidebar > .nav-item {
    .nav-treeview,
    > .nav-treeview {
      background-color: rgba($white, .05) !important ;

      .nav-item {
        > .nav-link {
          border-left: .2rem solid !important ;
        }
      }
    }
  }
}

.nav-legacy {
  margin: (-$sidebar-padding-x * .5) (-$sidebar-padding-x) 0 !important ;

  &.nav-sidebar .nav-item {
    > .nav-link {
      border-radius: 0 !important ;
      margin-bottom: 0 !important ;

      > .nav-icon {
        margin-left: .55rem !important ;

        .text-sm & {
          margin-left: .75rem !important ;
        }
      }
    }
  }

  &.nav-sidebar > .nav-item {
    > .nav-link {
      &.active {
        background-color: inherit !important ;
        border-left: 3px solid transparent !important ;
        box-shadow: none !important ;

        > .nav-icon {
          margin-left: calc(.55rem - 3px) !important ;

          .text-sm & {
            margin-left: calc(.75rem - 3px) !important ;
          }
        }
      }
    }
  }

  .text-sm &.nav-sidebar.nav-flat .nav-treeview {
    .nav-item {
      > .nav-link {
        > .nav-icon {
          margin-left: calc(.75rem - 3px) !important ;
        }
      }
    }
  }

  .sidebar-mini &,
  .sidebar-mini-md &,
  .sidebar-mini-xs & {
    > .nav-item .nav-link {
      .nav-icon {
        @include transition(margin-left $transition-fn $transition-speed) !important ;
        margin-left: .6rem !important ;
      }
    }
  }

  .sidebar-mini.sidebar-collapse,
  .sidebar-mini-md.sidebar-collapse,
  .sidebar-mini-xs.sidebar-collapse {
    .main-sidebar.sidebar-focused &.nav-child-indent,
    .main-sidebar:hover &.nav-child-indent {
      .nav-treeview {
        padding-left: 1rem !important ;

        .nav-treeview {
          padding-left: 2rem !important ;
          margin-left: -1rem !important ;
        }
      }
    }
  }

  .sidebar-mini.sidebar-collapse.text-sm,
  .sidebar-mini-md.sidebar-collapse.text-sm,
  .sidebar-mini-xs.sidebar-collapse.text-sm {
    .main-sidebar.sidebar-focused &.nav-child-indent,
    .main-sidebar:hover &.nav-child-indent {
      .nav-treeview {
        padding-left: .5rem !important ;

        .nav-treeview {
          padding-left: 1rem !important ;
          margin-left: -.5rem !important ;
        }
      }
    }
  }

  .sidebar-mini.sidebar-collapse &,
  .sidebar-mini-md.sidebar-collapse &,
  .sidebar-mini-xs.sidebar-collapse & {
    .sidebar {
      > .nav-item > .nav-link {
        .nav-icon {
          margin-left: .55rem !important ;
        }
        &.active {
          > .nav-icon {
            margin-left: .36rem !important ;
          }
        }
      }
      &.nav-child-indent {
        .nav-treeview {
          .nav-treeview {
            padding-left: 0 !important ;
            margin-left: 0 !important ;
          }
        }
      }
    }
  }

  .sidebar-mini.sidebar-collapse.text-sm &,
  .sidebar-mini-md.sidebar-collapse.text-sm &,
  .sidebar-mini-xs.sidebar-collapse.text-sm & {
    .sidebar {
      > .nav-item > .nav-link {
        .nav-icon {
          margin-left: .75rem !important ;
        }

        &.active {
          > .nav-icon {
            margin-left: calc(.75rem - 3px) !important ;
          }
        }
      }
    }
  }

  [class*="sidebar-dark"] & {
    &.nav-sidebar > .nav-item {
      .nav-treeview,
      > .nav-treeview {
        background-color: rgba($white, .05) !important ;
      }

      > .nav-link.active {
        color: $sidebar-dark-active-color !important ;
      }
    }

    .nav-treeview > .nav-item > .nav-link {
      &.active,
      &:focus,
      &:hover {
        background-color: transparent !important ;
        color: $sidebar-dark-active-color !important ;
      }
    }
  }

  [class*="sidebar-light"] & {
    &.nav-sidebar > .nav-item {
      .nav-treeview,
      > .nav-treeview {
        background-color: rgba($black, .05) !important ;
      }

      > .nav-link.active {
        color: $sidebar-light-active-color !important ;
      }
    }

    .nav-treeview > .nav-item > .nav-link {
      &.active,
      &:focus,
      &:hover {
        background-color: transparent !important ;
        color: $sidebar-light-active-color !important ;
      }
    }
  }
}

.nav-collapse-hide-child {
  .menu-open > .nav-treeview {
    max-height: min-content !important ;
    animation-name: fadeIn !important ;
    animation-duration: $transition-speed !important ;
    animation-fill-mode: both !important ;
  }

  .sidebar-collapse .sidebar:not(:hover) & {
    .menu-open > .nav-treeview {
      max-height: 0 !important ;
      animation-name: fadeOut !important ;
      animation-duration: $transition-speed !important ;
      animation-fill-mode: both !important ;
    }
  }

  .sidebar-mini.sidebar-collapse,
  .sidebar-mini-md.sidebar-collapse,
  .sidebar-mini-xs.sidebar-collapse {
    .main-sidebar.sidebar-focused &,
    .main-sidebar:not(.sidebar-no-expand):hover & {
      .menu-open > .nav-treeview {
        max-height: min-content !important ;
        animation-name: fadeIn !important ;
        animation-duration: $transition-speed !important ;
        animation-fill-mode: both !important ;
      }
    }
  }
}

// Nav Compact
.nav-compact {
  .nav-link,
  .nav-header {
    padding-top: ($nav-link-padding-y * .5) !important ;
    padding-bottom: ($nav-link-padding-y * .5) !important ;
  }

  .nav-header:not(:first-of-type) {
    padding-top: ($nav-link-padding-y * 1.5) !important ;
    padding-bottom: ($nav-link-padding-y * .5) !important ;
  }

  .nav-link > .right,
  .nav-link > p > .right {
    top: .465rem !important ;
  }

  .text-sm & {
    .nav-link > .right,
    .nav-link > p > .right {
      top: .7rem !important ;
    }
  }
}

// Sidebar Form Control
[class*="sidebar-dark"] {
  .form-control-sidebar,
  .btn-sidebar {
    background-color: lighten($sidebar-dark-bg, 5%) !important ;
    border: 1px solid lighten($sidebar-dark-bg, 15%) !important ;
    color: lighten(color-yiq(lighten($sidebar-dark-bg, 5%)), 15%) !important ;
  }

  .form-control-sidebar:focus,
  .btn-sidebar:focus {
    border: 1px solid lighten($sidebar-dark-bg, 30%) !important ;
  }

  .btn-sidebar:hover {
    background-color: lighten($sidebar-dark-bg, 7.5%) !important ;
  }

  .btn-sidebar:focus {
    background-color: lighten($sidebar-dark-bg, 10%) !important ;
  }

  .list-group-item {
    background-color: lighten($sidebar-dark-bg, 7.5%) !important ;
    border-color: lighten($sidebar-dark-bg, 15%) !important ;
    color: $sidebar-dark-color !important ;

    &:hover {
      background-color: lighten($sidebar-dark-bg, 10%) !important ;
    }

    &:focus {
      background-color: lighten($sidebar-dark-bg, 12.5%) !important ;
    }

    .search-path {
      color: $gray-500 !important ;
    }
  }
}

[class*="sidebar-light"] {
  .form-control-sidebar,
  .btn-sidebar {
    background-color: darken($sidebar-light-bg, 5%) !important ;
    border: 1px solid darken($sidebar-light-bg, 15%) !important ;
    color: color-yiq(darken($sidebar-light-bg, 5%)) !important ;
  }

  .form-control-sidebar:focus,
  .btn-sidebar:focus {
    border: 1px solid darken($sidebar-light-bg, 30%) !important ;
  }

  .btn-sidebar:hover {
    background-color: darken($sidebar-light-bg, 7.5%) !important ;
  }

  .btn-sidebar:focus {
    background-color: darken($sidebar-light-bg, 10%) !important ;
  }

  .list-group-item {
    border-color: darken($sidebar-light-bg, 15%) !important ;

    &:hover {
      background-color: darken($sidebar-light-bg, 7.5%) !important ;
    }

    &:focus {
      background-color: darken($sidebar-light-bg, 10%) !important ;
    }

    .search-path {
      color: $gray-600 !important ;
    }
  }
}

// Sidebar inline input-group fix
.sidebar .form-inline .input-group {
  width: 100% !important ;
  flex-wrap: nowrap !important ;
}
.sidebar nav .form-inline {
  margin-bottom: .2rem !important ;
}

// Sidebar Collapse on Layout Boxed
.layout-boxed:not(.sidebar-mini):not(.sidebar-mini-md):not(.sidebar-mini-xs) {
  &.sidebar-collapse .main-sidebar {
    margin-left: 0 !important ;
  }
  .content-wrapper,
  .main-header,
  .main-footer {
    z-index: 9999 !important ;
    position: relative !important ;
  }
  .control-sidebar {
    z-index: 9999 !important ;
  }
}

// Sidebar Search
.sidebar-collapse {
  .form-control-sidebar,
  .form-control-sidebar ~ .input-group-append,
  .sidebar-search-results {
    display: none !important ;
  }
}

[data-widget="sidebar-search"] {
  input[type="search"] {
    &::-ms-clear,
    &::-ms-reveal {
      display: none !important ;
      width: 0 !important ;
      height: 0 !important ;
    }

    &::-webkit-search-cancel-button,
    &::-webkit-search-decoration,
    &::-webkit-search-results-button,
    &::-webkit-search-results-decoration {
      display: none !important ;
    }
  }
}

.sidebar-search-results {
  position: relative !important ;
  display: none !important ;
  width: 100% !important ;

  .sidebar-search-open & {
    display: inline-block !important ;
  }

  .search-title {
    margin-bottom: -.1rem !important ;
  }

  .list-group {
    position: absolute !important ;
    width: 100% !important ;
    z-index: $zindex-main-sidebar + 1 !important ;

    > .list-group-item {
      padding: $input-padding-y $input-padding-x !important ;

      &:-moz-focusring {
        margin-top: 0 !important ;
        border-left: 1px solid transparent !important ;
        border-top: 0 !important ;
        border-bottom: 1px solid transparent !important ;
      }

      &:first-child {
        margin-top: 0 !important ;
        border-top: 0 !important ;
        @include border-top-radius(0) !important ;
      }
    }
  }
}

.sidebar-search-results .search-path {
  font-size: $small-font-size !important ;
}

.sidebar-search-open {
  .btn,
  .form-control {
    @include border-bottom-radius(0) !important ;
  }
}

// Custom Area
.sidebar-custom {
  [class*="sidebar-dark"] & {
    border-top: 1px solid lighten($dark, 12%) !important ;
  }

  [class*="sidebar-light"] & {
    border-top: 1px solid $gray-300 !important ;
  }
}

.layout-fixed {
  &.sidebar-collapse {
    .hide-on-collapse {
      display: none !important ;
    }
  }

  &.sidebar-collapse:hover {
    .hide-on-collapse {
      display: block !important ;
    }
  }

  &.text-sm .main-sidebar-custom {
    .sidebar {
      height: calc(100% - ((#{$main-header-height-sm-inner} + #{$sidebar-custom-height * .95}) + #{$main-header-bottom-border-width})) !important ;
    }
    .sidebar-custom {
      height: $sidebar-custom-height * .95 !important ;
      padding: $sidebar-custom-padding-x $sidebar-custom-padding-y !important ;
    }
  }
  .main-sidebar-custom {
    .sidebar {
      height: calc(100% - ((#{$main-header-height-inner} + #{$sidebar-custom-height}) + #{$main-header-bottom-border-width})) !important ;
    }

    .sidebar-custom {
      height: $sidebar-custom-height !important ;
      padding: $sidebar-custom-padding-x $sidebar-custom-padding-y !important ;
    }

    height: stretch !important ;
  }

  .main-sidebar-custom-lg {
    .sidebar {
      height: calc(100% - ((#{$main-header-height-inner} + #{$sidebar-custom-height-lg}) + #{$main-header-bottom-border-width})) !important ;
    }

    .sidebar-custom {
      height: $sidebar-custom-height-lg !important ;
    }
  }

  .main-sidebar-custom-xl {
    .sidebar {
      height: calc(100% - ((#{$main-header-height-inner} + #{$sidebar-custom-height-xl}) + #{$main-header-bottom-border-width})) !important ;
    }

    .sidebar-custom {
      height: $sidebar-custom-height-xl !important ;
    }
  }

  .main-sidebar-custom,
  .main-sidebar-custom-lg,
  .main-sidebar-custom-xl {
    .pos-right {
      position: absolute !important ;
      right: .5rem !important ;
    }
  }
}

.sidebar-hidden,
.sidebar-hidden.sidebar-mini.sidebar-collapse {
  .main-sidebar {
    display: none !important !important ;
  }
  .content-wrapper,
  .main-header {
    margin-left: 0 !important !important ;
  }
}

@include dark-mode() {
  @each $name, $color in $theme-colors-alt {
    .sidebar-dark-#{$name},
    .sidebar-light-#{$name} {
      @include sidebar-color($color) !important ;
    }
  }

  @each $name, $color in $colors-alt {
    .sidebar-dark-#{$name},
    .sidebar-light-#{$name} {
      @include sidebar-color($color) !important ;
    }
  }

  [class*="sidebar-light-"] {
    .sidebar {
      a {
        color: $sidebar-light-color !important ;

        &:hover {
          text-decoration: none !important ;
        }
      }
    }
  }
}

