/**
  * bootstrap-switch - Turn checkboxes and radio buttons into toggle switches.
  *
  * @version v3.4 (MODDED)
  * @homepage https://bttstrp.github.io/bootstrap-switch
  * @author Mattia Larentis <mattia@larentis.eu> (http://larentis.eu)
  * @license MIT
  */

$bootstrap-switch-border-radius: $btn-border-radius !important ;
$bootstrap-switch-handle-border-radius: .1rem !important ;

.bootstrap-switch {
  border: $input-border-width solid $input-border-color !important ;
  border-radius: $bootstrap-switch-border-radius !important ;
  cursor: pointer !important ;
  direction: ltr !important ;
  display: inline-block !important ;
  line-height: .5rem !important ;
  overflow: hidden !important ;
  position: relative !important ;
  text-align: left !important ;
  transition: border-color ease-in-out .15s, box-shadow ease-in-out .15s !important ;
  user-select: none !important ;
  vertical-align: middle !important ;
  z-index: 0 !important ;

  .bootstrap-switch-container {
    border-radius: $bootstrap-switch-border-radius !important ;
    display: inline-block !important ;
    top: 0 !important ;
    transform: translate3d(0, 0, 0) !important ;

  }

  &:focus-within {
    box-shadow: $input-btn-focus-box-shadow !important ;
  }

  .bootstrap-switch-handle-on,
  .bootstrap-switch-handle-off,
  .bootstrap-switch-label {
    box-sizing: border-box !important ;
    cursor: pointer !important ;
    display: table-cell !important ;
    font-size: 1rem !important ;
    font-weight: 500 !important ;
    line-height: 1.2rem !important ;
    padding: .25rem .5rem !important ;
    vertical-align: middle !important ;
  }

  .bootstrap-switch-handle-on,
  .bootstrap-switch-handle-off {
    text-align: center !important ;
    z-index: 1 !important ;

    &.bootstrap-switch-default {
      background: $gray-200 !important ;
      color: color-yiq($gray-200) !important ;
    }

    @each $name, $color in $theme-colors {
      &.bootstrap-switch-#{$name} {
        background: $color !important ;
        color: color-yiq($color) !important ;
      }
    }

    @each $name, $color in $colors {
      &.bootstrap-switch-#{$name} {
        background: $color !important ;
        color: color-yiq($color) !important ;
      }
    }
  }

  .bootstrap-switch-handle-on {
    border-bottom-left-radius: $bootstrap-switch-handle-border-radius !important ;
    border-top-left-radius: $bootstrap-switch-handle-border-radius !important ;
  }

  .bootstrap-switch-handle-off {
    border-bottom-right-radius: $bootstrap-switch-handle-border-radius !important ;
    border-top-right-radius: $bootstrap-switch-handle-border-radius !important ;
  }

  input[type='radio'],
  input[type='checkbox'] {
    filter: alpha(opacity=0) !important ;
    left: 0 !important ;
    margin: 0 !important ;
    opacity: 0 !important ;
    position: absolute !important ;
    top: 0 !important ;
    visibility: hidden !important ;
    z-index: -1 !important ;
  }

  &.bootstrap-switch-mini {
    .bootstrap-switch-handle-on,
    .bootstrap-switch-handle-off,
    .bootstrap-switch-label {
      font-size: .875rem !important ;
      line-height: 1.5 !important ;
      padding: .1rem .3rem !important ;
    }
  }

  &.bootstrap-switch-small {
    .bootstrap-switch-handle-on,
    .bootstrap-switch-handle-off,
    .bootstrap-switch-label {
      font-size: .875rem !important ;
      line-height: 1.5 !important ;
      padding: .2rem .4rem !important ;
    }
  }

  &.bootstrap-switch-large {
    .bootstrap-switch-handle-on,
    .bootstrap-switch-handle-off,
    .bootstrap-switch-label {
      font-size: 1.25rem !important ;
      line-height: 1.3333333rem !important ;
      padding: .3rem .5rem !important ;
    }
  }

  &.bootstrap-switch-disabled,
  &.bootstrap-switch-readonly,
  &.bootstrap-switch-indeterminate {
    cursor: default !important ;

    .bootstrap-switch-handle-on,
    .bootstrap-switch-handle-off,
    .bootstrap-switch-label {
      cursor: default !important ;
      filter: alpha(opacity=50) !important ;
      opacity: .5 !important ;
    }
  }

  &.bootstrap-switch-animate .bootstrap-switch-container {
    transition: margin-left .5s !important ;
  }

  &.bootstrap-switch-inverse {
    .bootstrap-switch-handle-on {
      border-radius: 0 $bootstrap-switch-handle-border-radius $bootstrap-switch-handle-border-radius 0 !important ;
    }

    .bootstrap-switch-handle-off {
      border-radius: $bootstrap-switch-handle-border-radius 0 0 $bootstrap-switch-handle-border-radius !important ;
    }
  }

  // &.bootstrap-switch-focused {
  //   border-color: $input-btn-focus-color !important ;
  //   box-shadow: $input-btn-focus-box-shadow !important ;
  //   outline: 0 !important ;
  // }

  &.bootstrap-switch-on .bootstrap-switch-label,
  &.bootstrap-switch-inverse.bootstrap-switch-off .bootstrap-switch-label {
    border-bottom-right-radius: $bootstrap-switch-handle-border-radius !important ;
    border-top-right-radius: $bootstrap-switch-handle-border-radius !important ;
  }

  &.bootstrap-switch-off .bootstrap-switch-label,
  &.bootstrap-switch-inverse.bootstrap-switch-on .bootstrap-switch-label {
    border-bottom-left-radius: $bootstrap-switch-handle-border-radius !important ;
    border-top-left-radius: $bootstrap-switch-handle-border-radius !important ;
  }
}

@include dark-mode () {
  .bootstrap-switch {
    border-color: $gray-600 !important ;

    .bootstrap-switch-handle-off.bootstrap-switch-default,
    .bootstrap-switch-handle-on.bootstrap-switch-default {
      background-color: lighten($dark, 2.5%) !important ;
      color: $white !important ;
      border-color: lighten($dark, 7.5%) !important ;
    }
    .bootstrap-switch-handle-on,
    .bootstrap-switch-handle-off {
      @each $name, $color in $theme-colors-alt {
        &.bootstrap-switch-#{$name} {
          background: $color !important ;
          color: color-yiq($color) !important ;
        }
      }

      @each $name, $color in $colors-alt {
        &.bootstrap-switch-#{$name} {
          background: $color !important ;
          color: color-yiq($color) !important ;
        }
      }
    }
  }
}
