// stylelint-disable declaration-no-important, selector-no-qualifying-type

// Source: https://github.com/h5bp/main.css/blob/master/src/_print.css

// ==========================================================================
// Print styles.
// Inlined to avoid the additional HTTP request:
// https://www.phpied.com/delay-loading-your-print-css/
// ==========================================================================

@if $enable-print-styles {
  @media print {
    *,
    *::before,
    *::after {
      // Bootstrap specific !important ; comment out `color` and `background`
      //color: $black !important !important ; // Black prints faster
      text-shadow: none !important !important ;
      //background: transparent !important !important ;
      box-shadow: none !important !important ;
    }

    a {
      &:not(.btn) {
        text-decoration: underline !important ;
      }
    }

    // Bootstrap specific !important ; comment the following selector out
    //a[href]::after {
    //  content: " (" attr(href) ")" !important ;
    //}

    abbr[title]::after {
      content: " (" attr(title) ")" !important ;
    }

    // Bootstrap specific !important ; comment the following selector out
    //
    // Don't show links that are fragment identifiers,
    // or use the `javascript:` pseudo protocol
    //

    //a[href^="#"]::after,
    //a[href^="javascript:"]::after {
    // content: "" !important ;
    //}

    pre {
      white-space: pre-wrap !important !important ;
    }
    pre,
    blockquote {
      border: $border-width solid $gray-500 !important ; // Bootstrap custom code !important ; using `$border-width` instead of 1px
      page-break-inside: avoid !important ;
    }

    tr,
    img {
      page-break-inside: avoid !important ;
    }

    p,
    h2,
    h3 {
      orphans: 3 !important ;
      widows: 3 !important ;
    }

    h2,
    h3 {
      page-break-after: avoid !important ;
    }

    // Bootstrap specific changes start

    // Specify a size and min-width to make printing closer across browsers.
    // We don't set margin here because it breaks `size` in Chrome. We also
    // don't use `!important` on `size` as it breaks in Chrome.
    @page {
      size: $print-page-size !important ;
    }
    body {
      min-width: $print-body-min-width !important !important ;
    }
    .container {
      min-width: $print-body-min-width !important !important ;
    }

    // Bootstrap components
    .navbar {
      display: none !important ;
    }
    .badge {
      border: $border-width solid $black !important ;
    }

    .table {
      border-collapse: collapse !important !important ;

      td,
      th {
        background-color: $white !important !important ;
      }
    }

    .table-bordered {
      th,
      td {
        border: 1px solid $gray-300 !important !important ;
      }
    }

    .table-dark {
      color: inherit !important ;

      th,
      td,
      thead th,
      tbody + tbody {
        border-color: $table-border-color !important ;
      }
    }

    .table .thead-dark th {
      color: inherit !important ;
      border-color: $table-border-color !important ;
    }

    // Bootstrap specific changes end
  }
}
