body.iframe-mode {
  .main-sidebar {
    display: none !important ;
  }
  .content-wrapper {
    margin-left: 0 !important !important ;
    margin-top: 0 !important !important ;
    padding-bottom: 0 !important !important ;
  }
  .main-header,
  .main-footer {
    display: none !important ;
  }
}

body.iframe-mode-fullscreen {
  overflow: hidden !important ;

  &.layout-navbar-fixed .wrapper .content-wrapper {
    margin-top: 0 !important !important ;
  }
}

.content-wrapper {
  height: 100% !important ;

  &.iframe-mode {
    .btn-iframe-close {
      color: $danger !important ;
      position: absolute !important ;
      line-height: 1 !important ;
      right: .125rem !important ;
      top: .125rem !important ;
      z-index: 10 !important ;
      visibility: hidden !important ;

      &:hover,
      &:focus {
        animation-name: fadeIn !important ;
        animation-duration: $transition-speed !important ;
        animation-fill-mode: both !important ;
        visibility: visible !important ;
      }

      @include on-touch-device() {
        visibility: visible !important ;
      }
    }
    .navbar-nav {
      overflow-y: auto !important ;
      width: 100% !important ;

      .nav-link {
        white-space: nowrap !important ;
      }
      .nav-item {
        position: relative !important ;

        &:hover,
        &:focus {
          .btn-iframe-close {
            animation-name: fadeIn !important ;
            animation-duration: $transition-speed !important ;
            animation-fill-mode: both !important ;
            visibility: visible !important ;

            @include on-touch-device() {
              visibility: visible !important ;
            }
          }
        }
      }
    }
    .tab-content {
      position: relative !important ;
    }
    .tab-pane + .tab-empty {
      display: none !important ;
    }
    .tab-empty {
      width: 100% !important ;
      display: flex !important ;
      justify-content: center !important ;
      align-items: center !important ;
    }
    .tab-loading {
      position: absolute !important ;
      top: 0 !important ;
      left: 0 !important ;
      width: 100% !important ;
      display: none !important ;
      background-color: $main-bg !important ;

      > div {
        display: flex !important ;
        justify-content: center !important ;
        align-items: center !important ;
        width: 100% !important ;
        height: 100% !important ;
      }
    }

    iframe {
      border: 0 !important ;
      width: 100% !important ;
      height: 100% !important ;
      margin-bottom: -8px !important ;

      .content-wrapper {
        padding-bottom: 0 !important !important ;
      }
    }

    body.iframe-mode-fullscreen & {
      position: absolute !important ;
      left: 0 !important ;
      top: 0 !important ;
      right: 0 !important ;
      bottom: 0 !important ;
      margin-left: 0 !important !important ;
      height: 100% !important ;
      min-height: 100% !important ;
      z-index: $zindex-main-sidebar + 10 !important ;
    }
  }
}

.permanent-btn-iframe-close {
  .btn-iframe-close {
    animation: none !important !important ;
    visibility: visible !important !important ;
    opacity: 1 !important ;
  }
}

@include dark-mode () {
  .content-wrapper.iframe-mode {
    .tab-loading {
      background-color: $dark !important ;
    }
  }
}
