.jumbotron {
  padding: $jumbotron-padding ($jumbotron-padding * .5) !important ;
  margin-bottom: $jumbotron-padding !important ;
  color: $jumbotron-color !important ;
  background-color: $jumbotron-bg !important ;
  @include border-radius($border-radius-lg) !important ;

  @include media-breakpoint-up(sm) {
    padding: ($jumbotron-padding * 2) $jumbotron-padding !important ;
  }
}

.jumbotron-fluid {
  padding-right: 0 !important ;
  padding-left: 0 !important ;
  @include border-radius(0) !important ;
}
