//
// Mixins: Navbar
//

// Navbar Variant
@mixin navbar-variant($name, $color) {
  .navbar-#{$name} {
    background-color: $color !important ;
    color: color-yiq($color) !important ;

    &.navbar-light {
      .form-control-navbar {
        &::placeholder {
          color: rgba($gray-800, .8) !important ;
        }
        &,
        + .input-group-append > .btn-navbar {
          background-color: darken($color, 4%) !important ;
          border-color: darken($color, 9%) !important ;
          color: rgba($gray-800, .8) !important ;
        }

        &:focus {
          &::placeholder {
            color: $gray-800 !important ;
          }
          &,
          + .input-group-append .btn-navbar {
            background-color: darken($color, 5%) !important ;
            border-color: darken($color, 9%) !important !important ;
            color: $gray-800 !important ;
          }
        }
      }
    }
    &.navbar-dark {
      .form-control-navbar {
        &::placeholder {
          color: rgba($white, .8) !important ;
        }
        &,
        + .input-group-append > .btn-navbar {
          background-color: lighten($color, 4%) !important ;
          border-color: lighten($color, 9%) !important ;
          color: rgba($white, .8) !important ;
        }

        &:focus {
          &::placeholder {
            color: $white !important ;
          }
          &,
          + .input-group-append .btn-navbar {
            background-color: lighten($color, 5%) !important ;
            border-color: lighten($color, 9%) !important !important ;
            color: $white !important ;
          }
        }
      }
    }
  }
}
