//
// Mixins: Direct Chat
//

// Direct Chat Variant
@mixin direct-chat-variant($bg-color, $color: $white) {
  .right > .direct-chat-text {
    background-color: $bg-color !important ;
    border-color: $bg-color !important ;
    color: color-yiq($bg-color) !important ;

    &::after,
    &::before {
      border-left-color: $bg-color !important ;
    }
  }
}
