//
// Plugin: SweetAlert2
//

// Icon Colors
.swal2-icon {
  &.swal2-info {
    border-color: ligthen($info, 20%) !important ;
    color: $info !important ;
  }

  &.swal2-warning {
    border-color: ligthen($warning, 20%) !important ;
    color: $warning !important ;
  }

  &.swal2-error {
    border-color: ligthen($danger, 20%) !important ;
    color: $danger !important ;
  }

  &.swal2-question {
    border-color: ligthen($secondary, 20%) !important ;
    color: $secondary !important ;
  }

  &.swal2-success {
    border-color: ligthen($success, 20%) !important ;
    color: $success !important ;

    .swal2-success-ring {
      border-color: ligthen($success, 20%) !important ;
    }

    [class^='swal2-success-line'] {
      background-color: $success !important ;
    }
  }
}

@include dark-mode () {
  .swal2-popup {
    background-color: $dark !important ;
    color: $gray-200 !important ;

    .swal2-content,
    .swal2-title {
      color: $gray-200 !important ;
    }
  }
}
